(window.TRENER_PACKS=window.TRENER_PACKS||{})["zadanie-1-stroenie-atoma"]={"id": "zadanie-1-stroenie-atoma", "subject": "Химия", "title": "Задание 1 · Строение атома и электронные конфигурации (с 0 до 100 баллов)", "version": "26.11.2026", "konspekt": "zadanie-1-stroenie-atoma", "codes": ["1.1"], "kod": {"p": [{"id": "p1", "t": "Состав атома и чтение чёрно-белой таблицы ФИПИ", "x": "Порядковый номер Z равен заряду ядра, числу протонов и числу электронов в нейтральном атоме; число нейтронов N = A − Z. В чёрно-белой таблице ФИПИ элементы главной подгруппы (А) всегда выровнены по тому же краю столбца, что и элементы малых периодов (2–3-го), а побочной (Б) — по противоположному.", "ref": "01.1"}, {"id": "p2", "t": "Уровни (2n²), принцип Паули и правило Хунда", "x": "Число энергетических уровней равно номеру периода n, максимальная ёмкость слоя — 2n² электронов (на 2-м уровне только 2s и 2p, подуровня 2d не существует). В одной орбитали помещается не более 2 электронов с противоположными спинами (Паули), а в пределах одного подуровня электроны сначала занимают свободные клетки по одному (Хунд).", "ref": "02.1"}, {"id": "p3", "t": "Правило Клечковского и семейства элементов", "x": "Подуровни заполняются по возрастанию суммы n + l, а при равной сумме — по возрастанию n: 1s → 2s → 2p → 3s → 3p → 4s → 3d → 4p → 5s → 4d → 5p. Семейство (s, p, d, f) определяется последним заполняемым подуровнем; для d-элементов 4-го периода конфигурацию записывают по слоям: [Ar]3d^k 4s^m.", "ref": "03.1"}, {"id": "p4", "t": "Провал (проскок) электрона у Cr и Cu", "x": "Наполовину заполненный (3d⁵) и полностью заполненный (3d¹⁰) предвнешние подуровни обладают повышенной устойчивостью. Поэтому в 4-м периоде один электрон с 4s переходит на 3d у хрома (₂₄Cr: [Ar]3d⁵4s¹, 6 неспаренных) и меди (₂₉Cu: [Ar]3d¹⁰4s¹, 1 неспаренный); аналоги в 5-м периоде — Mo и Ag.", "ref": "04.1"}, {"id": "p5", "t": "Внешние, предвнешние и валентные электроны", "x": "Внешние электроны — строго электроны самого последнего слоя (max n): у d-элементов 4-го периода это только 4s¹ или 4s². Валентные электроны участвуют в образовании связей: для s/p-элементов это ns + np (= номер группы А), для переходных d-элементов Sc–Cu — ns + (n−1)d, а у Zn закрытый 3d¹⁰ не валентен (только 2 валентных — 4s²).", "ref": "05.1"}, {"id": "p6", "t": "Основное и возбуждённое состояния атома", "x": "Возбуждение в рамках ЕГЭ — распаривание электронной пары в пределах того же внешнего уровня n на свободную орбиталь того же уровня. Оно возможно только при одновременном наличии электронной пары и пустой орбитали на слое n (Be, B, C, Si, P, S, Cl); каждая ступень увеличивает число неспаренных электронов на 2.", "ref": "06.1"}, {"id": "p7", "t": "Конфигурации ионов и оболочка благородного газа", "x": "При образовании катиона атом отдаёт электроны с самого внешнего уровня: у d-металлов 4-го периода сначала всегда уходят электроны с 4s, и только затем с 3d (Fe²⁺ = [Ar]3d⁶, Fe³⁺ = [Ar]3d⁵, Cr³⁺ = [Ar]3d³). Конфигурацию благородного газа имеют только частицы вида 1s² или ns²np⁶.", "ref": "07.1"}, {"id": "p8", "t": "Боевой 5-шаговый алгоритм для задания № 1 КИМ", "x": "В задании № 1 всегда 5 элементов и ровно 2 верных номера (1 балл, порядок цифр не важен). Выпиши конфигурации всех пяти элементов, отметь ловушки (Cr, Cu, He, Zn, N/O/F), подчеркни слова-переключатели в условии (внешние/валентные/всего, основное/возбуждённое, атом/ион) и проверь все признаки для каждого элемента.", "ref": "08.1"}], "z": [{"id": "z1", "x": "У хлора Ar = 35,45 из-за природной смеси изотопов ³⁵Cl (75%) и ³⁷Cl (25%): у наиболее распространённого изотопа ³⁵Cl 17 протонов и 18 нейтронов (p ≠ n).", "sk": "atom_pshe", "ref": "01.12"}, {"id": "z2", "x": "Гелий (₂He, 1s²) — это строго s-элемент (не p-элемент!), имеющий 2 внешних электрона (конфигурация ns², как у Be, Mg, Ca, Fe, Zn) и 0 неспаренных электронов.", "sk": "klechkovsky_spd", "ref": "03.15"}, {"id": "z3", "x": "Только 4 элемента всей Периодической системы содержат исключительно s-электроны (не имеют p-электронов): H, He, Li и Be.", "sk": "klechkovsky_spd", "ref": "03.18"}, {"id": "z4", "x": "В 4-м периоде провал электрона происходит строго у двух элементов: ₂₄Cr ([Ar]3d⁵4s¹ — 6 неспаренных, 1 внешний, 7 s-электронов всего) и ₂₉Cu ([Ar]3d¹⁰4s¹ — 1 неспаренный, 1 внешний, 7 s-электронов всего).", "sk": "d_promotion", "ref": "04.19"}, {"id": "z5", "x": "У p-элементов 4-го периода (Ga, Ge, As, Se, Br, Kr) в конфигурации [Ar]3d¹⁰4s²4p^k присутствует полностью заполненный 3d-подуровень (3d¹⁰), как у Cu и Zn.", "sk": "klechkovsky_spd", "ref": "03.15"}, {"id": "z6", "x": "У цинка ₃₀Zn ([Ar]3d¹⁰4s²) полностью заполненный 3d¹⁰-подуровень в образовании связей не участвует, поэтому у Zn ровно 2 внешних и 2 валентных электрона.", "sk": "outer_valence", "ref": "05.7"}, {"id": "z7", "x": "Водороду H (1s¹) до завершения внешнего уровня (дублета 1s²) недостаёт ровно 1 электрона, а не 7 — так же, как галогенам F, Cl, Br, I до октета.", "sk": "outer_valence", "ref": "05.13"}, {"id": "z8", "x": "Атомы N, O и F (2-й период) НЕ переходят в возбуждённое состояние: на 2-м уровне нет 2d-подуровня и нет пустых 2p-орбиталей. Максимальная валентность азота равна IV.", "sk": "excited_state", "ref": "06.8"}, {"id": "z9", "x": "При ионизации d-металлов 4-го периода электроны всегда сначала уходят с внешнего 4s-подуровня, а не с 3d: Fe²⁺ = [Ar]3d⁶, Fe³⁺ = [Ar]3d⁵, Cr³⁺ = [Ar]3d³, Cu⁺ = [Ar]3d¹⁰.", "sk": "ions_noble", "ref": "07.8"}, {"id": "z10", "x": "Ионы с 18-электронной оболочкой [Ar]3d¹⁰ (Cu⁺, Zn²⁺, Ga³⁺, Ge⁴⁺) НЕ имеют электронной конфигурации аргона или другого благородного газа.", "sk": "ions_noble", "ref": "07.13"}, {"id": "z11", "x": "Различай «уровень, содержащий электроны» (= номер периода) и «полностью заполненный уровень» (2n²): у Ar, K, Ca, Sc–Ni полностью заполнены только 2 уровня (1-й и 2-й), а 3-й уровень (18 e⁻) становится полностью заполненным только начиная с Cu и Zn.", "sk": "kim1_strategy", "ref": "08.11"}, {"id": "z12", "x": "Стандарт записи ФИПИ: заряд иона пишется цифрой перед знаком (Fe^{2+}, O^{2−}, S^{2−}), а степень окисления — знаком перед цифрой (Fe^{+2}, O^{−2}, N^{+5}).", "sk": "ions_noble", "ref": "07.5"}]}, "skills": [{"id": "atom_pshe", "name": "Ядро, изотопы и чёрно-белая таблица ФИПИ", "ref": "01", "idea": "Безошибочно определять число протонов, нейтронов и электронов в атоме/изотопе и мгновенно отличать подгруппы А и Б в чёрно-белом бланке ФИПИ.", "pre": {"type": "one", "q": "У наиболее распространённого изотопа какого химического элемента число протонов в ядре РАВНО числу нейтронов?", "o": ["Кальций (Ca, Z = 20, Ar = 40,08)", "Хлор (Cl, Z = 17, Ar = 35,45)", "Алюминий (Al, Z = 13, Ar = 26,98)", "Фтор (F, Z = 9, Ar = 19,00)"], "a": 0, "ex": "У основного изотопа ⁴⁰Ca число протонов p = 20, число нейтронов N = 40 − 20 = 20 (p = N).", "d": {"1": "У хлора в природе смесь ³⁵Cl (17 p, 18 n) и ³⁷Cl (17 p, 20 n) — ни у одного природного изотопа p не равно n.", "2": "У алюминия ²⁷Al: p = 13, N = 27 − 13 = 14 (нейтронов на 1 больше).", "3": "У фтора ¹⁹F: p = 9, N = 19 − 9 = 10 (нейтронов на 1 больше)."}}, "pair": {"type": "one", "cases": [["Хром (₂₄Cr, VI группа, 4-й период)", "Символ в чёрно-белой таблице ФИПИ сдвинут в сторону, противоположную O и S → побочная подгруппа (VIB)"], ["Селен (₃₄Se, VI группа, 4-й период)", "Символ выровнен по тому же краю, что и O и S из 2–3 периодов → главная подгруппа (VIA)"]], "q": "Как без цветной раскраски определить в таблице ФИПИ, какой элемент 4-го периода относится к главной подгруппе (А), а какой — к побочной (Б)?", "o": ["Сравнить выравнивание символа в столбце с элементами 2–3-го периодов той же группы: совпадает — главная (А), сдвинут в противоположную сторону — побочная (Б)", "Элементы с чётным номером Z всегда стоят в главной подгруппе, а с нечётным — в побочной", "Все металлы 4-го периода относятся к побочным подгруппам, а все неметаллы — к главным", "В 4-м периоде первый ряд (K–Ni) — всегда главные подгруппы, а второй ряд (Cu–Kr) — побочные"], "a": 0, "ex": "В малых периодах (2-м и 3-м) стоят только элементы главных подгрупп (А), поэтому их выравнивание в столбце служит безошибочным ориентиром для всей группы."}, "fade": {"q": "Восстанови правила подсчёта частиц в нейтральном атоме и его изотопах:", "steps": ["Число протонов в ядре равно {порядковому номеру Z|номеру группы|массовому числу A}, а в нейтральном атоме оно совпадает с числом {электронов|нейтронов|энергетических уровней}.", "Число нейтронов в ядре конкретного изотопа вычисляется по формуле {N = A − Z|N = A + Z|N = 2Z}.", "Дробная атомная масса хлора (35,45) объясняется наличием в природе смеси {изотопов ³⁵Cl и ³⁷Cl|катионов и анионов хлора|основного и возбуждённого состояний Cl}."]}, "bug": {"q": "Найди ошибочный шаг в определении числа нейтронов у наиболее распространённых изотопов (¹⁶O, ²³Na, ³⁵Cl, ³²S):", "steps": ["Для ¹⁶O (Z = 8): N = 16 − 8 = 8 нейтронов, значит p = N.", "Для ²³Na (Z = 11): N = 23 − 11 = 12 нейтронов, значит p ≠ N.", "Для Cl (Z = 17, Ar = 35,45): округляем 35,5 до 36, получаем N = 36 − 17 = 19 нейтронов.", "Для ³²S (Z = 16): N = 32 − 16 = 16 нейтронов, значит p = N."], "bad": 2, "fix": "Относительная атомная масса Cl = 35,45 — среднее по смеси ³⁵Cl (75%) и ³⁷Cl (25%); у наиболее распространённого изотопа ³⁵Cl число нейтронов равно 35 − 17 = 18.", "why": "Изотопа ³⁶Cl среди стабильных природных изотопов хлора нет; округлять 35,45 до 36 — грубая ошибка."}, "recall": {"q": "Назови по памяти 4 главных правила работы с ядром и чёрно-белой таблицей ФИПИ.", "points": ["p = Z (протоны = порядковый номер = электроны в нейтральном атоме); N = A − Z (нейтроны).", "Изотопы — атомы одного элемента с одинаковым Z (числом протонов), но разным массовым числом A (числом нейтронов).", "Хлор (35,45) — природная смесь ³⁵Cl (75%, 18 n) и ³⁷Cl (25%, 20 n); ни у одного p ≠ n.", "В чёрно-белой таблице ФИПИ главная подгруппа (А) выровнена так же, как элементы 2–3 периодов в том же столбце."]}}, {"id": "orbitals_hund", "name": "Уровни, орбитали, Паули и правило Хунда", "ref": "02", "idea": "Точно расселять электроны по энергетическим ячейкам и считать число спаренных, неспаренных электронов и занятых орбиталей в основном состоянии.", "pre": {"type": "one", "q": "Сколько неспаренных электронов содержится в основном состоянии атома кислорода (₈O: 1s²2s²2p⁴)?", "o": ["2", "0", "4", "6"], "a": 0, "ex": "На трёх 2p-орбиталях сначала расселяются по одному 3 электрона (↑ ↑ ↑), а 4-й образует пару в первой клетке (↑↓ ↑ ↑) — остаётся ровно 2 неспаренных электрона.", "d": {"1": "0 неспаренных было бы при нарушении правила Хунда (↑↓ ↑↓ _), что энергетически невыгодно.", "2": "4 — это общее число 2p-электронов, из них два уже спарены в одной ячейке.", "3": "6 — это число всех внешних электронов (2s²2p⁴), из них 4 спарены и 2 неспарены."}}, "pair": {"type": "one", "cases": [["Углерод (₆C: 1s²2s²2p²)", "2 электрона на трёх 2p-ячейках сидят по одному (↑ ↑ _) → 2 неспаренных электрона"], ["Бериллий (₄Be: 1s²2s²)", "2 электрона на одной 2s-ячейке спарены (↑↓) → 0 неспаренных электронов"]], "q": "Почему у бериллия (2s²) нет неспаренных электронов, а у углерода на 2p² их сразу два?", "o": ["На s-подуровне всего 1 орбиталь (два электрона вынуждены спариться), а на p-подуровне 3 равноценные орбитали — по правилу Хунда электроны занимают их по одному", "На 2s-подуровне не действует принцип Паули", "У углерода два электрона переходят на 2d-подуровень уже в основном состоянии", "У бериллия оба электрона находятся на разных энергетических уровнях"], "a": 0, "ex": "Количество орбиталей на подуровнях: s — 1 клетка, p — 3 клетки, d — 5 клеток, f — 7 клеток. По правилу Хунда свободные клетки одного подуровня сначала заполняются поодиночке."}, "fade": {"q": "Заполни ключевые числовые характеристики уровней и правил заселения орбиталей:", "steps": ["Максимальное число электронов на n-м энергетическом уровне вычисляется по формуле {2n²|n²|2n+2}: на 2-м уровне максимум {8|18|2} электронов, на 3-м — {18|8|32}.", "Число орбиталей (клеток) на подуровнях: на s — {1|2|3}, на p — {3|6|5}, на d — {5|10|7}.", "По принципу Паули в одной орбитали может находиться не более {2|1|4} электронов с {противоположными|одинаковыми|нулевыми} спинами."]}, "bug": {"q": "Найди ошибочный шаг в подсчёте неспаренных электронов в основном состоянии для элементов 2-го периода (Li, Be, B, C, N, O):", "steps": ["У Li (2s¹) — 1 неспаренный, у Be (2s²) — 0 неспаренных, у B (2s²2p¹) — 1 неспаренный.", "У C (2s²2p²) два электрона на 2p² образуют пару в первой ячейке (↑↓ _ _), значит 0 неспаренных.", "У N (2s²2p³) три электрона занимают три 2p-ячейки по одному (↑ ↑ ↑) — 3 неспаренных.", "У O (2s²2p⁴) четвёртый p-электрон образует пару (↑↓ ↑ ↑) — остаётся 2 неспаренных."], "bad": 1, "fix": "По правилу Хунда у углерода 2p² электроны занимают две разные орбитали по одному (↑ ↑ _), поэтому у C ровно 2 неспаренных электрона.", "why": "Спаривание в одной клетке требует дополнительной энергии отталкивания, поэтому при наличии пустых клеток на том же подуровне электроны всегда расселяются поодиночке."}, "recall": {"q": "Назови по памяти 3 правила заселения орбиталей и число неспаренных электронов для конфигураций p¹–p⁶.", "points": ["Принцип минимума энергии: сначала заполняются подуровни с меньшей энергией.", "Принцип Паули: в одной орбитали максимум 2 электрона с противоположными спинами.", "Правило Хунда: в пределах одного подуровня электроны сначала занимают свободные ячейки по одному с параллельными спинами.", "Число неспаренных электронов на p-подуровне: p¹ → 1, p² → 2, p³ → 3, p⁴ → 2, p⁵ → 1, p⁶ → 0."]}}, {"id": "klechkovsky_spd", "name": "Правило Клечковского, семейства и подсчёт s/p/d", "ref": "03", "idea": "Строить конфигурации по правилу Клечковского, определять семейство элемента (включая He и Ga–Kr) и без ошибок суммировать все s-, p- и d-электроны атома.", "pre": {"type": "one", "q": "Почему у калия (₁₉K) девятнадцатый электрон занимает подуровень 4s, а не 3d?", "o": ["Сумма n + l для 4s (4 + 0 = 4) меньше, чем для 3d (3 + 2 = 5), поэтому 4s ниже по энергии", "У калия на третьем энергетическом уровне нет d-подуровня", "Подуровень 3d заполняется только у неметаллов", "У 4s больше значение главного квантового числа n, поэтому он заполняется первым"], "a": 0, "ex": "По правилу Клечковского сначала сравнивают n + l: для 4s это 4 + 0 = 4, а для 3d это 3 + 2 = 5 (4 < 5 → 4s заполняется раньше).", "d": {"1": "3d-подуровень существует на третьем уровне (n = 3, l = 2), просто он выше по энергии, чем 4s.", "2": "3d-подуровень заполняется именно у d-металлов (Sc–Zn).", "3": "При равном n + l раньше заполняется подуровень с МЕНЬШИМ n, а не с большим."}}, "pair": {"type": "one", "cases": [["Кислород (₈O: 1s²2s²2p⁴)", "Всего s-электронов: 2 + 2 = 4; всего p-электронов: 4 (равны!)"], ["Магний (₁₂Mg: 1s²2s²2p⁶3s²)", "Всего s-электронов: 2 + 2 + 2 = 6; всего p-электронов: 6 (равны!)"]], "q": "Какую ошибку чаще всего совершают выпускники, решая задачу «у каких элементов число s-электронов равно числу p-электронов»?", "o": ["Считают s- и p-электроны только на внешнем уровне вместо суммы по всем энергетическим уровням атома", "Считают электроны только на первом уровне 1s²", "Забывают, что у магния есть p-электроны на внешнем 3-м уровне", "Относят магний к p-элементам"], "a": 0, "ex": "Если в условии не сказано «на внешнем уровне», суммируются все s- и все p-электроны со всех слоёв атома (у Mg: 1s²+2s²+3s² = 6 и 2p⁶ = 6)."}, "fade": {"q": "Восстанови порядок заполнения подуровней и правила классификации семейств:", "steps": ["По правилу Клечковского после 3p заполняется {4s|3d|4p}, затем {3d|4p|5s}, а после него — {4p|4d|5s}.", "Гелий (₂He, 1s²) по последнему заполняемому подуровню относится к {s-элементам|p-элементам|d-элементам}.", "У p-элементов 4-го периода (Ga–Kr) предвнешний 3d-подуровень {полностью заполнен (3d¹⁰)|пуст|содержит 5 электронов}."]}, "bug": {"q": "Найди ошибочный шаг в решении задания № 1 из ДЕМО-2027 («число s-электронов равно числу s-электронов в катионе Na⁺» из ряда: O, F, Al, Si, Li):", "steps": ["У нейтрального Na (1s²2s²2p⁶3s¹) 5 s-электронов; при образовании Na⁺ уходит 3s¹, остаётся 1s²2s²2p⁶ → 4 s-электрона.", "У O (1s²2s²2p⁴) и F (1s²2s²2p⁵) по 2 + 2 = 4 s-электрона → оба подходят.", "У Al (1s²2s²2p⁶3s²3p¹) на внешнем уровне 2 s-электрона, а у Si (3s²3p²) тоже 2 s-электрона, но с учётом внутренних слоёв их по 6.", "У Li (1s²2s¹) на внешнем уровне 1 s-электрон, а всего 1 + 1 = 2 s-электрона."], "bad": 3, "fix": "У лития Li (1s²2s¹) всего 2 + 1 = 3 s-электрона (два на 1s² и один на 2s¹), а не 2.", "why": "Даже при верном итоговом ответе (O и F) нельзя терять второй электрон на 1s²: в другом варианте КИМ вопрос может быть именно про 3 s-электрона!"}, "recall": {"q": "Назови по памяти цепочку Клечковского до 5p и две главные ловушки семейств.", "points": ["Цепочка заполнения: 1s → 2s → 2p → 3s → 3p → 4s → 3d → 4p → 5s → 4d → 5p.", "Двухчастное правило Клечковского: сначала меньше (n + l), при равенстве — меньше n (l: s=0, p=1, d=2, f=3).", "Ловушка 1: He (1s²) — s-элемент, а не p-элемент.", "Ловушка 2: Ga–Kr — p-элементы, но у них уже есть полностью заполненный 3d¹⁰-подуровень."]}}, {"id": "d_promotion", "name": "d-элементы 4-го периода и провал электрона (Cr, Cu)", "ref": "04", "idea": "Мгновенно записывать конфигурации всех десяти d-элементов Sc–Zn, уверенно выделять провал у Cr и Cu (и Mo, Ag) и не ошибаться в числе их неспаренных и s-электронов.", "pre": {"type": "one", "q": "Какова правильная электронная конфигурация внешнего и предвнешнего уровней атома хрома (₂₄Cr) в основном состоянии?", "o": ["[Ar]3d⁵4s¹", "[Ar]3d⁴4s²", "[Ar]3d⁶4s⁰", "[Ar]3d⁵4s²"], "a": 0, "ex": "У хрома происходит провал (проскок) одного электрона с 4s на 3d ради устойчивого наполовину заполненного 3d⁵-подуровня: [Ar]3d⁵4s¹ (6 неспаренных электронов).", "d": {"1": "Это «наивная» конфигурация без учёта провала электрона — главная ловушка КИМ № 1.", "2": "Переходят не оба 4s-электрона, а только один (на 4s остаётся 1 e⁻).", "3": "Сумма электронов [Ar]3d⁵4s² равна 25 — это марганец Mn, а не хром Cr."}}, "pair": {"type": "one", "cases": [["Хром (₂₄Cr: [Ar]3d⁵4s¹)", "Провал 4s → 3d даёт 6 неспаренных электронов, 1 внешний и всего 7 s-электронов"], ["Медь (₂₉Cu: [Ar]3d¹⁰4s¹)", "Провал 4s → 3d даёт 1 неспаренный электрон (на 4s¹), 1 внешний и всего 7 s-электронов"]], "q": "Что ОБЩЕГО в основном состоянии у атомов хрома (Cr) и меди (Cu) именно благодаря провалу электрона?", "o": ["Оба имеют ровно 1 электрон на внешнем уровне (4s¹) и ровно 7 s-электронов во всём атоме (1s²2s²3s²4s¹)", "Оба имеют по 6 неспаренных электронов", "Оба имеют полностью заполненный 3d¹⁰-подуровень", "Оба относятся к s-элементам из-за конфигурации 4s¹"], "a": 0, "ex": "У Cr и Cu из-за перехода одного электрона с 4s на 3d остаётся 4s¹ (1 внешний электрон и 2 + 2 + 2 + 1 = 7 s-электронов всего), как у калия K ([Ar]4s¹)."}, "fade": {"q": "Заполни ключевые факты о d-элементах и провале электрона:", "steps": ["В 4-м периоде провал электрона происходит строго у двух элементов: {Cr и Cu|Cr и Mn|Cu и Zn}.", "У хрома (₂₄Cr: [Ar]3d⁵4s¹) в основном состоянии ровно {6|4|5} неспаренных электронов, а у меди (₂₉Cu: [Ar]3d¹⁰4s¹) — ровно {1|0|2}.", "В 5-м периоде классическими аналогами Cr и Cu с таким же провалом 5s → 4d являются {Mo и Ag|Mn и Zn|Rb и Sr}."]}, "bug": {"q": "Найди ошибочный шаг в сравнении четырёх d-элементов (Cr, Mn, Fe, Cu) по числу неспаренных и s-электронов:", "steps": ["У Cr ([Ar]3d⁵4s¹) 6 неспаренных электронов и 7 s-электронов во всём атоме.", "У Mn ([Ar]3d⁵4s²) 5 неспаренных электронов и 8 s-электронов во всём атоме.", "У Fe ([Ar]3d⁶4s²) 4 неспаренных электрона и 8 s-электронов во всём атоме.", "У Cu ([Ar]3d⁹4s²) 1 неспаренный электрон и 8 s-электронов во всём атоме."], "bad": 3, "fix": "У меди Cu происходит провал электрона: правильная конфигурация [Ar]3d¹⁰4s¹ — 1 неспаренный электрон (на 4s¹) и 7 s-электронов во всём атоме.", "why": "Хотя число неспаренных случайно совпало (1), запись 3d⁹4s² даёт неверное число внешних электронов (2 вместо 1), неверное число s-электронов (8 вместо 7) и скрывает закрытый 3d¹⁰."}, "recall": {"q": "Назови по памяти конфигурации, число внешних, неспаренных и s-электронов для Cr, Mn, Fe, Cu и Zn.", "points": ["₂₄Cr: [Ar]3d⁵4s¹ — 1 внешний, 6 неспаренных, 7 s-электронов.", "₂₅Mn: [Ar]3d⁵4s² — 2 внешних, 5 неспаренных, 8 s-электронов.", "₂₆Fe: [Ar]3d⁶4s² — 2 внешних, 4 неспаренных, 8 s-электронов.", "₂₉Cu: [Ar]3d¹⁰4s¹ — 1 внешний, 1 неспаренный, 7 s-электронов; ₃₀Zn: [Ar]3d¹⁰4s² — 2 внешних, 0 неспаренных, 8 s-электронов."]}}, {"id": "outer_valence", "name": "Внешние, предвнешние и валентные электроны", "ref": "05", "idea": "Чётко разделять внешние и валентные электроны у s-, p- и d-элементов (включая He и Zn), находить одинаковые внешние оболочки и число электронов до завершения уровня.", "pre": {"type": "one", "q": "У какого из перечисленных элементов число ВАЛЕНТНЫХ электронов равно 6, а число ВНЕШНИХ электронов равно 1?", "o": ["Хром (₂₄Cr)", "Сера (₁₆S)", "Марганец (₂₅Mn)", "Цинк (₃₀Zn)"], "a": 0, "ex": "У хрома ([Ar]3d⁵4s¹) на внешнем 4-м уровне всего 1 электрон (4s¹), а валентными являются 3d⁵ + 4s¹ = 6 электронов.", "d": {"1": "У серы ([Ne]3s²3p⁴) и внешних, и валентных электронов по 6.", "2": "У марганца ([Ar]3d⁵4s²) 2 внешних электрона и 7 валентных.", "3": "У цинка ([Ar]3d¹⁰4s²) 2 внешних и 2 валентных электрона (3d¹⁰ закрыт)."}}, "pair": {"type": "one", "cases": [["Водород (₁H: 1s¹)", "Внешний 1-й уровень вмещает максимум 2 e⁻ → до завершения недостаёт 1 электрона"], ["Фтор (₉F: 2s²2p⁵)", "Внешний 2-й уровень завершается октетом (8 e⁻) → до завершения недостаёт 1 электрона"]], "q": "Почему в задании № 1 водород H и галогены (F, Cl) попадают в один ответ на вопрос «до завершения внешнего уровня недостаёт 1 электрона»?", "o": ["У водорода внешний уровень — первый (максимум 2 e⁻, дублет 1s²), поэтому к 1s¹ не хватает ровно 1 e⁻, как и к ns²np⁵ до октета", "Водород стоит в VII группе и имеет 7 внешних электронов", "У водорода и фтора одинаковое число энергетических уровней", "Водород является p-элементом 1-го периода"], "a": 0, "ex": "Завершённый внешний уровень для 1-го периода — дублет 1s² (2 e⁻), для остальных периодов — октет ns²np⁶ (8 e⁻). Поэтому H (2 − 1 = 1) и F/Cl (8 − 7 = 1) совпадают."}, "fade": {"q": "Восстанови границы терминов «внешние» и «валентные» электроны:", "steps": ["У s- и p-элементов число внешних электронов {равно числу валентных|меньше числа валентных|всегда равно 2}.", "У переходных d-элементов Sc–Cu валентными являются электроны {ns и (n−1)d|только ns|только (n−1)d}, а внешними — только {ns|(n−1)d|ns и np}.", "У цинка ₃₀Zn ([Ar]3d¹⁰4s²) полностью заполненный 3d¹⁰-подуровень в образовании связей не участвует, поэтому число валентных электронов равно {2|12|10}."]}, "bug": {"q": "Найди ошибочный шаг в поиске элементов с одинаковой электронной конфигурацией внешнего уровня ns² среди ряда (He, Mg, Fe, Cr, Zn):", "steps": ["У Mg ([Ne]3s²) внешний уровень — 3s² (тип ns²) → подходит.", "У Fe ([Ar]3d⁶4s²) и Zn ([Ar]3d¹⁰4s²) внешний уровень — 4s² (тип ns²) → оба подходят.", "У Cr ([Ar]3d⁵4s¹) из-за провала внешний уровень — 4s¹ (тип ns¹) → не подходит.", "У He (1s²) внешний уровень завершён (благородный газ), поэтому его конфигурация не совпадает с ns² у Mg."], "bad": 3, "fix": "У гелия He (1s²) конфигурация внешнего уровня имеет вид ns² (при n = 1), поэтому в заданиях № 1 ЕГЭ он совпадает по виду внешнего уровня с Be, Mg, Ca и d-металлами без провала!", "why": "То, что 1s² завершён, не отменяет формулу ns² — это одна из самых частых ловушек КИМ № 1."}, "recall": {"q": "Назови по памяти 4 главные ловушки по внешним и валентным электронам в задании № 1.", "points": ["Внешние электроны = только слой max n (у d-металлов 1 у Cr/Cu и 2 у остальных Sc–Zn).", "Валентные электроны у d-металлов Sc–Cu = ns + (n−1)d (у Cr — 6, у Mn — 7, у Fe — 8); у Zn — только 2 (4s²).", "Одинаковая внешняя оболочка ns¹ объединяет H, Li, Na, K, Rb, Cs и Cr, Cu; оболочка ns² — He, Be, Mg, Ca, Sr, Ba и Sc–Ni, Zn.", "До завершения внешнего уровня водороду H не хватает 1 e⁻ (до 1s²), а не 7."]}}, {"id": "excited_state", "name": "Основное и возбуждённое состояния атома", "ref": "06", "idea": "Определять возможность перехода атома в возбуждённое состояние, строить ступени распаривания (Be, B, C, Si, P, S, Cl) и безошибочно отсекать N, O, F.", "pre": {"type": "one", "q": "Атом какого из перечисленных элементов НЕ СПОСОБЕН переходить в возбуждённое состояние в пределах внешнего энергетического уровня?", "o": ["Азот (₇N)", "Углерод (₆C)", "Фосфор (₁₅P)", "Сера (₁₆S)"], "a": 0, "ex": "У азота (2s²2p³) на 2-м уровне все три 2p-орбитали заняты, а 2d-подуровня в природе не существует — электрону из пары 2s² некуда перейти.", "d": {"1": "У углерода (2s²2p²) есть 1 пустая 2p-орбиталь → возбуждается в 2s¹2p³ (4 неспаренных).", "2": "У фосфора (3s²3p³3d⁰) есть свободный 3d-подуровень → возбуждается в 3s¹3p³3d¹ (5 неспаренных).", "3": "У серы (3s²3p⁴3d⁰) есть свободный 3d-подуровень → 2 ступени возбуждения (4 и 6 неспаренных)."}}, "pair": {"type": "one", "cases": [["Азот (₇N: 2s²2p³)", "На 2-м уровне нет 2d-подуровня и нет пустых 2p-клеток → НЕ возбуждается (макс. валентность IV)"], ["Фосфор (₁₅P: 3s²3p³3d⁰)", "На 3-м уровне есть пустой 3d-подуровень → возбуждается в 3s¹3p³3d¹ (5 неспаренных, валентность V)"]], "q": "Почему фосфор способен проявлять валентность V (например, в PCl5), а его сосед сверху по VA группе — азот — ограничен максимальной валентностью IV?", "o": ["У фосфора на 3-м уровне есть пустой 3d-подуровень для распаривания 3s², а у азота на 2-м уровне 2d-подуровня нет", "У азота меньше электронов на внешнем уровне, чем у фосфора", "У фосфора происходит провал электрона с 4s на 3d", "Азот не способен образовывать связи по донорно-акцепторному механизму"], "a": 0, "ex": "Наличие пустого 3d-подуровня открывает возбуждённые состояния для P (5 несп.), S (4 и 6 несп.) и Cl (3, 5 и 7 несп.), тогда как N, O и F не возбуждаются."}, "fade": {"q": "Восстанови ступени возбуждения и число неспаренных электронов для элементов 2–3 периодов:", "steps": ["При каждой ступени возбуждения распадается 1 электронная пара, поэтому число неспаренных электронов увеличивается на {2|1|3}.", "У углерода C (2s²2p²) возможно возбуждение в {2s¹2p³|2s²2p¹2d¹|2s⁰2p⁴} с {4|3|6} неспаренными электронами.", "У серы S (3s²3p⁴) в 1-м возбуждённом состоянии конфигурация {3s²3p³3d¹|3s¹3p⁴3d¹|3s²3p²3d²} (4 неспаренных), а во 2-м — {3s¹3p³3d²|3s²3p²3d²|3s⁰3p⁴3d²} (6 неспаренных)."]}, "bug": {"q": "Найди ошибочный шаг в разборе возбуждённых состояний для ряда элементов (B, C, N, S, Cl):", "steps": ["Бор B (2s²2p¹) имеет пустые 2p-ячейки → возбуждается в 2s¹2p² (3 неспаренных).", "Углерод C (2s²2p²) имеет 1 пустую 2p-ячейку → возбуждается в 2s¹2p³ (4 неспаренных).", "Азот N (2s²2p³) в HNO3 имеет степень окисления +5, значит он возбуждается в 2s¹2p³2d¹ (5 неспаренных).", "Хлор Cl (3s²3p⁵3d⁰) имеет 3 пары и пустой 3d → даёт 3, 5 или 7 неспаренных электронов."], "bad": 2, "fix": "На 2-м уровне не существует 2d-подуровня, поэтому азот N не переходит в возбуждённое состояние; в HNO3 его степень окисления +5, а валентность равна IV (три обменные + одна донорно-акцепторная связь).", "why": "Нельзя путать степень окисления (+5) и число неспаренных электронов/валентность (у азота максимум 3 неспаренных и валентность IV)."}, "recall": {"q": "Назови по памяти два обязательных условия возбуждения и перечень элементов 2–3 периодов, которые НЕ возбуждаются.", "points": ["Два условия: на внешнем уровне n есть хотя бы одна электронная пара И хотя бы одна пустая орбиталь того же уровня n.", "Не возбуждаются из-за отсутствия пары: H, Li, Na, K (ns¹).", "Не возбуждаются из-за отсутствия пустых орбиталей: He, Ne, N, O, F (нет 2d!).", "Максимум неспаренных при возбуждении: Be/Mg → 2, B/Al → 3, C/Si → 4, P → 5, S → 6, Cl → 7."]}}, {"id": "ions_noble", "name": "Электронные конфигурации ионов и благородных газов", "ref": "07", "idea": "Безошибочно составлять конфигурации катионов (сначала убирая 4s у d-металлов!) и анионов, находить изоэлектронные ряды и отсекать псевдоинертную ловушку [Ar]3d¹⁰.", "pre": {"type": "one", "q": "Какова электронная конфигурация катиона железа(II) Fe^{2+} (Z = 26)?", "o": ["[Ar]3d⁶", "[Ar]3d⁴4s²", "[Ar]3d⁵4s¹", "[Ar]3d⁵"], "a": 0, "ex": "Нейтральный атом Fe имеет конфигурацию [Ar]3d⁶4s². При ионизации сначала уходят 2 электрона с внешнего 4s-подуровня, остаётся [Ar]3d⁶.", "d": {"1": "Ошибка: электроны удалили с предвнешнего 3d вместо внешнего 4s.", "2": "Это конфигурация нейтрального атома хрома Cr (24 e⁻), но у катиона Fe^{2+} уровень 4s пуст.", "3": "[Ar]3d⁵ — это конфигурация катиона железа(III) Fe^{3+} (ушли 4s² и один 3d)."}}, "pair": {"type": "one", "cases": [["Катион скандия Sc^{3+} (Z = 21)", "Уходят 4s² и 3d¹ → остаётся 1s²2s²2p⁶3s²3p⁶ = [Ar] (конфигурация аргона)"], ["Катион цинка Zn^{2+} (Z = 30)", "Уходят 4s² → остаётся [Ar]3d¹⁰ (28 e⁻ — НЕ совпадает ни с Ar (18), ни с Kr (36))"]], "q": "Почему катионы Zn^{2+}, Cu^{+} и Ga^{3+} НЕ подходят под формулировку ЕГЭ «имеют электронную конфигурацию благородного (инертного) газа»?", "o": ["Их оболочка [Ar]3d¹⁰ содержит 28 электронов (18 на 3-м слое), тогда как у всех благородных газов оболочка имеет вид 1s² или ns²np⁶ (у Ar — 18 e⁻, у Kr — 36 e⁻)", "Переходные металлы вообще не способны образовывать ионы с конфигурацией благородного газа", "У катиона Zn^{2+} остаются электроны на 4s-подуровне", "Конфигурацию благородного газа могут иметь только анионы неметаллов, но не катионы"], "a": 0, "ex": "Конфигурацию аргона [Ar] (18 e⁻) имеют S^{2−}, Cl^{−}, K^{+}, Ca^{2+}, Sc^{3+}, а [Ar]3d¹⁰ (28 e⁻) — это 18-электронная псевдоинертная оболочка, но не благородный газ."}, "fade": {"q": "Восстанови правила составления конфигураций ионов и стандарт их записи:", "steps": ["При образовании катиона d-металла 4-го периода электроны всегда сначала уходят с подуровня {4s|3d|3p}, и только затем — с {3d|4s|4p}.", "У катиона Cr^{3+} (нейтральный Cr: [Ar]3d⁵4s¹) конфигурация равна {[Ar]3d³|[Ar]3d²4s¹|[Ar]3d⁴4s⁰}, а у Fe^{3+} — {[Ar]3d⁵|[Ar]3d³4s²|[Ar]3d⁶}.", "По стандарту ФИПИ заряд иона записывается {цифрой перед знаком (Fe^{2+}, S^{2−})|знаком перед цифрой (Fe^{+2}, S^{−2})|в любом порядке}."]}, "bug": {"q": "Найди ошибочный шаг в определении конфигураций ионов (O^{2−}, Al^{3+}, Cr^{3+}, Cu^{+}, Ga^{3+}):", "steps": ["O^{2−} (8 + 2 = 10 e⁻): 1s²2s²2p⁶ — конфигурация неона [Ne].", "Al^{3+} (13 − 3 = 10 e⁻): 1s²2s²2p⁶ — конфигурация неона [Ne].", "Cr^{3+} (нейтральный [Ar]3d⁵4s¹ − 3 e⁻): уходит 4s¹ и два 3d → [Ar]3d³.", "Cu^{+} (29 − 1 = 28 e⁻) и Ga^{3+} (31 − 3 = 28 e⁻): оба имеют [Ar]3d¹⁰, что соответствует конфигурации аргона."], "bad": 3, "fix": "Cu^{+} и Ga^{3+} действительно изоэлектронны друг другу ([Ar]3d¹⁰, 28 e⁻), но это НЕ конфигурация аргона (18 e⁻) и не конфигурация какого-либо благородного газа!", "why": "Присутствие 3d¹⁰ в записи [Ar]3d¹⁰ сразу показывает 10 лишних электронов сверх конфигурации аргона."}, "recall": {"q": "Назови по памяти конфигурации Fe^{2+}, Fe^{3+}, Cr^{3+}, Cu^{+}, Zn^{2+} и два главных изоэлектронных ряда (10 e⁻ и 18 e⁻).", "points": ["Fe^{2+} = [Ar]3d⁶; Fe^{3+} = [Ar]3d⁵; Cr^{3+} = [Ar]3d³; Cu^{+} = [Ar]3d¹⁰; Zn^{2+} = [Ar]3d¹⁰.", "Изоэлектронный ряд неона [Ne] (10 e⁻): N^{3−}, O^{2−}, F^{−}, Ne, Na^{+}, Mg^{2+}, Al^{3+}.", "Изоэлектронный ряд аргона [Ar] (18 e⁻): P^{3−}, S^{2−}, Cl^{−}, Ar, K^{+}, Ca^{2+}, Sc^{3+}.", "Ловушка: [Ar]3d¹⁰ (Cu^{+}, Zn^{2+}, Ga^{3+}, Ge^{4+}) — 28 e⁻, НЕ благородный газ!"]}}, {"id": "kim1_strategy", "name": "Стратегия № 1 КИМ и слова-переключатели", "ref": "08", "idea": "Распознавать все 12 типов формулировок КИМ № 1, мгновенно различать слова-переключатели (уровень/подуровень/орбиталь, заполненный/содержащий) и решать комбинированные задачи без ошибок.", "pre": {"type": "one", "q": "Сколько ПОЛНОСТЬЮ ЗАПОЛНЕННЫХ энергетических уровней (по формуле 2n²) содержит атом калия (₁₉K: 1s²2s²2p⁶3s²3p⁶4s¹)?", "o": ["2 (только 1-й и 2-й уровни)", "3 (1-й, 2-й и 3-й уровни)", "4 (все уровни 4-го периода)", "1 (только 1-й уровень)"], "a": 0, "ex": "На 3-м уровне максимальная ёмкость 2·3² = 18 электронов (3s²3p⁶3d¹⁰), а у калия там только 8 (3d пуст). Поэтому полностью заполнены строго 2 уровня: 1-й (2 e⁻) и 2-й (8 e⁻).", "d": {"1": "Частая ловушка: 3-й уровень у K, Ca и Sc–Ni не заполнен полностью из-за пустого или недозаполненного 3d.", "2": "4 — это число уровней, СОДЕРЖАЩИХ электроны (номер периода), а не полностью заполненных.", "3": "2-й уровень (2s²2p⁶ = 8 e⁻) тоже полностью заполнен."}}, "pair": {"type": "one", "cases": [["Углерод (₆C: 1s²2s²2p²)", "Занято 2 уровня, 3 подуровня (1s, 2s, 2p), 4 орбитали (1 + 1 + 2), из них 2 полностью заполненные"], ["Аргон (₁₈Ar: 1s²2s²2p⁶3s²3p⁶)", "Внешний уровень завершён (октет 3s²3p⁶), но полностью заполненных уровней (2n²) всего 2 (3d пуст!)"]], "q": "Чем отличается «занятая орбиталь» от «занятого подуровня» в атоме углерода (1s²2s²2p²)?", "o": ["Подуровень — это слагаемое вида 1s, 2s, 2p (у C их 3), а орбиталь — отдельная квантовая ячейка (у C заняты 4 клетки: одна 1s, одна 2s и две 2p)", "Орбиталь и подуровень — синонимы, у углерода их по 3", "У углерода 2 орбитали (по номеру периода) и 6 подуровней (по числу электронов)", "На 2p² занята только 1 орбиталь, так как оба электрона спарены"], "a": 0, "ex": "Всегда различай иерархию: уровень (слой n) > подуровень (s, p, d) > орбиталь (клетка). У C: 2 уровня, 3 подуровня, 4 занятых орбитали."}, "fade": {"q": "Восстанови ключевые различия слов-переключателей в задании № 1 КИМ:", "steps": ["Число уровней, СОДЕРЖАЩИХ электроны, всегда равно {номеру периода|номеру группы|числу подуровней}.", "Третий энергетический уровень (18 e⁻) становится ПОЛНОСТЬЮ ЗАПОЛНЕННЫМ только начиная с элементов {Cu и Zn (и далее Ga–Kr)|Ar и K|Sc и Ti}.", "Если в условии написано «число s-электронов» БЕЗ слов «на внешнем уровне», нужно суммировать s-электроны {по всем уровням атома|только на внешнем уровне|только на 1s}."]}, "bug": {"q": "Найди ошибочный шаг в решении комбинированного задания № 1 («Выберите два элемента, у которых в основном состоянии ровно 1 неспаренный электрон И на внешнем уровне 1 электрон» из ряда: 1) Na  2) Cl  3) Cu  4) Al  5) Cr):", "steps": ["Выписываем конфигурации: Na (3s¹), Cl (3s²3p⁵), Cu ([Ar]3d¹⁰4s¹), Al (3s²3p¹), Cr ([Ar]3d⁵4s¹).", "Проверяем Фильтр 1 (ровно 1 неспаренный электрон): подходят Na (1), Cl (1), Cu (1), Al (1); Cr (6 неспаренных) вычёркиваем.", "Проверяем Фильтр 2 (1 электрон на внешнем уровне): подходят Na (3s¹) и Al (3p¹ — один электрон на последнем подуровне).", "Итоговый выбор по двум фильтрам должен дать ровно 2 цифры."], "bad": 2, "fix": "У Al (3s²3p¹) на внешнем 3-м уровне 2 + 1 = 3 электрона (не 1!), а у Cu ([Ar]3d¹⁰4s¹) — ровно 1 внешний электрон (4s¹). Верный ответ: Na и Cu (13).", "why": "Не путай «1 электрон на последнем подуровне» (3p¹ у Al) с «1 электроном на внешнем уровне» (3s¹ у Na, 4s¹ у Cu)."}, "recall": {"q": "Назови по памяти 5 шагов боевого алгоритма решения задания № 1 КИМ.", "points": ["Найти все 5 элементов в таблице ФИПИ, подписать Z, период и подгруппу (А/Б).", "Выписать электронные конфигурации всех 5 элементов на черновике, сразу помечая Cr, Cu, He, Zn, N/O/F.", "Подчеркнуть слова-переключатели (основное/возбуждённое, внешние/валентные/всего, атом/ион, заполненные/содержащие).", "Проверить каждый из 5 элементов по всем условиям и поставить «+» или «−».", "Убедиться, что плюсов ровно 2 (порядок цифр не важен), и перечитать условие с конца перед записью ответа."]}}], "figs": {}, "tab": [{"id": "t_nuclei", "t": "Состав ядра, изотопы и подгруппы А/Б в чёрно-белой таблице ФИПИ", "k": "Элемент / изотоп", "km": "элементом", "ref": "01.6", "n": 1, "lv3": ["³⁵Cl (основной изотоп хлора)", "²⁷Al (алюминий)", "₂₄Cr (хром, ⁵²Cr)", "₃₄Se (селен, ⁷⁹Se)"], "cols": [{"t": "Равенство протонов и нейтронов (p = N)", "sk": "atom_pshe", "n": 1, "q": "Равно ли число протонов числу нейтронов (p = N) в ядре {x}?", "m": "равенством числа протонов и нейтронов", "mq": "Выберите {k} частицы, для которых равенство p = N — «{v}»:"}, {"t": "Подгруппа в таблице ФИПИ", "sk": "atom_pshe", "n": 1, "q": "К какой подгруппе таблицы ФИПИ относится {x}?", "m": "подгруппой в таблице ФИПИ", "mq": "Выберите {k} элемента из подгруппы «{v}»:"}, {"t": "Состав ядра (p и N)", "sk": "atom_pshe", "n": 1, "q": "Какой состав ядра (число протонов и нейтронов) имеет {x}?", "m": "составом ядра (протоны и нейтроны)"}], "rows": [["¹⁶O (кислород)", "Да (p = N)", "Главная (А)", "8 протонов, 8 нейтронов"], ["³²S (сера)", "Да (p = N)", "Главная (А)", "16 протонов, 16 нейтронов"], ["⁴⁰Ca (кальций)", "Да (p = N)", "Главная (А)", "20 протонов, 20 нейтронов"], ["³⁵Cl (основной изотоп хлора)", "Нет (p ≠ N)", "Главная (А)", "17 протонов, 18 нейтронов"], ["²⁷Al (алюминий)", "Нет (p ≠ N)", "Главная (А)", "13 протонов, 14 нейтронов"], ["₂₄Cr (хром, ⁵²Cr)", "Нет (p ≠ N)", "Побочная (Б)", "24 протона, 28 нейтронов"], ["₃₄Se (селен, ⁷⁹Se)", "Нет (p ≠ N)", "Главная (А)", "34 протона, 45 нейтронов"], ["₂₆Fe (железо, ⁵⁶Fe)", "Нет (p ≠ N)", "Побочная (Б)", "26 протонов, 30 нейтронов"]], "rw": {"³⁵Cl (основной изотоп хлора)": "Ловушка! Ar(Cl) = 35,45 — смесь ³⁵Cl (18 n) и ³⁷Cl (20 n), ни у одного p ≠ n.", "₂₄Cr (хром, ⁵²Cr)": "В VI группе 4-го периода Cr сдвинут в сторону от O/S (побочная Б), а Se выровнен с O/S (главная А)."}}, {"id": "t_unpaired", "t": "Число неспаренных электронов и семейство в основном состоянии", "k": "Атом", "km": "атомом", "ref": "02.16", "n": 1, "lv3": ["₂He (гелий)", "₆C (углерод)", "₂₄Cr (хром)", "₂₉Cu (медь)", "₃₀Zn (цинк)"], "cols": [{"t": "Неспаренных e⁻ (осн. сост.)", "sk": "orbitals_hund", "n": 1, "q": "Сколько неспаренных электронов содержит атом {x} в основном состоянии?", "m": "числом неспаренных электронов в основном состоянии", "mq": "Выберите {k} атома с числом неспаренных электронов «{v}»:"}, {"t": "Электронное семейство", "sk": "klechkovsky_spd", "n": 1, "q": "К какому электронному семейству относится атом {x}?", "m": "электронным семейством", "mq": "Выберите {k} элемента, относящихся к семейству «{v}»:"}], "rows": [["₂He (гелий)", "0", "s-элемент"], ["₁₂Mg (магний)", "0", "s-элемент"], ["₆C (углерод)", "2", "p-элемент"], ["₇N (азот)", "3", "p-элемент"], ["₈O (кислород)", "2", "p-элемент"], ["₁₇Cl (хлор)", "1", "p-элемент"], ["₂₄Cr (хром)", "6", "d-элемент"], ["₂₅Mn (марганец)", "5", "d-элемент"], ["₂₉Cu (медь)", "1", "d-элемент"], ["₃₀Zn (цинк)", "0", "d-элемент"]], "rw": {"₂He (гелий)": "Гелий (1s²) — строго s-элемент, а не p-элемент! Неспаренных электронов 0.", "₂₄Cr (хром)": "Из-за провала [Ar]3d⁵4s¹ у хрома максимальное для 4-го периода число неспаренных — 6.", "₂₉Cu (медь)": "Из-за провала [Ar]3d¹⁰4s¹ единственный неспаренный электрон сидит на 4s¹."}}, {"id": "t_d_elements", "t": "d-элементы 4-го периода: конфигурация, внешние e⁻ и число всех s-электронов", "k": "d-элемент", "km": "d-элементом", "ref": "04.11", "n": 1, "lv3": ["₂₄Cr (хром)", "₂₅Mn (марганец)", "₂₆Fe (железо)", "₂₉Cu (медь)", "₃₀Zn (цинк)"], "cols": [{"t": "Конфигурация (после [Ar])", "sk": "d_promotion", "n": 1, "q": "Какая электронная конфигурация (после [Ar]) соответствует атому {x} в основном состоянии?", "m": "электронной конфигурацией после [Ar]"}, {"t": "Внешних электронов (4s)", "sk": "d_promotion", "n": 1, "q": "Сколько ВНЕШНИХ электронов (на 4-м слое) у атома {x} в основном состоянии?", "m": "числом внешних электронов", "mq": "Выберите {k} элемента, имеющих на внешнем уровне «{v}»:"}, {"t": "Всего s-электронов в атоме", "sk": "d_promotion", "n": 1, "q": "Сколько ВСЕГО s-электронов содержится в атоме {x} в основном состоянии?", "m": "общим числом s-электронов", "mq": "Выберите {k} элемента с общим числом s-электронов «{v}»:"}], "rows": [["₂₁Sc (скандий)", "3d¹4s²", "2", "8"], ["₂₂Ti (титан)", "3d²4s²", "2", "8"], ["₂₃V (ванадий)", "3d³4s²", "2", "8"], ["₂₄Cr (хром)", "3d⁵4s¹", "1", "7"], ["₂₅Mn (марганец)", "3d⁵4s²", "2", "8"], ["₂₆Fe (железо)", "3d⁶4s²", "2", "8"], ["₂₈Ni (никель)", "3d⁸4s²", "2", "8"], ["₂₉Cu (медь)", "3d¹⁰4s¹", "1", "7"], ["₃₀Zn (цинк)", "3d¹⁰4s²", "2", "8"]], "rw": {"₂₄Cr (хром)": "Провал 4s → 3d: остаётся 1 внешний электрон (4s¹) и 7 s-электронов всего (1s²2s²3s²4s¹).", "₂₉Cu (медь)": "Провал 4s → 3d: остаётся 1 внешний электрон (4s¹) и 7 s-электронов всего."}}, {"id": "t_outer_val", "t": "Внешние vs валентные электроны и тип внешней оболочки", "k": "Элемент", "km": "элементом", "ref": "05.5", "n": 1, "lv3": ["₂₄Cr (хром)", "₂₅Mn (марганец)", "₂₆Fe (железо)", "₃₀Zn (цинк)", "₂He (гелий)"], "cols": [{"t": "Тип внешнего уровня", "sk": "outer_valence", "n": 1, "q": "Какой общий вид имеет внешний энергетический уровень атома {x}?", "m": "общим видом внешнего уровня", "mq": "Выберите {k} элемента с конфигурацией внешнего уровня «{v}»:"}, {"t": "Число валентных электронов", "sk": "outer_valence", "n": 1, "q": "Сколько ВАЛЕНТНЫХ электронов в атоме {x} (в модели ЕГЭ)?", "m": "числом валентных электронов", "mq": "Выберите {k} элемента, у которых число валентных электронов равно «{v}»:"}], "rows": [["₁₁Na (натрий)", "ns¹", "1"], ["₁₂Mg (магний)", "ns²", "2"], ["₂He (гелий)", "ns²", "2 (завершён, инертен)"], ["₁₅P (фосфор)", "ns²np³", "5"], ["₁₆S (сера)", "ns²np⁴", "6"], ["₂₄Cr (хром)", "ns¹", "6"], ["₂₅Mn (марганец)", "ns²", "7"], ["₂₆Fe (железо)", "ns²", "8"], ["₃₀Zn (цинк)", "ns²", "2"]], "rw": {"₂₄Cr (хром)": "Внешний всего 1 (4s¹), но валентных сразу 6 (3d⁵ + 4s¹) — как у серы!", "₃₀Zn (цинк)": "Закрытый 3d¹⁰ не участвует в связях, поэтому валентных электронов только 2 (4s²)."}}, {"id": "t_excited", "t": "Основное и возбуждённое состояния элементов 2–3 периодов", "k": "Элемент", "km": "элементом", "ref": "06.12", "n": 1, "lv3": ["₇N (азот)", "₈O (кислород)", "₉F (фтор)", "₁₅P (фосфор)", "₁₆S (сера)", "₁₇Cl (хлор)"], "cols": [{"t": "Способность к возбуждению", "sk": "excited_state", "n": 1, "q": "Способен ли атом {x} переходить в возбуждённое состояние в пределах внешнего уровня?", "m": "способностью переходить в возбуждённое состояние", "mq": "Выберите {k} элемента, для которых способность к возбуждению — «{v}»:"}, {"t": "Неспаренных (осн. → возб.)", "sk": "excited_state", "n": 1, "q": "Как меняется число неспаренных электронов у атома {x} при переходе из основного в возбуждённые состояния?", "m": "числом неспаренных электронов в основном и возбуждённом состояниях"}], "rows": [["₄Be (бериллий)", "Да", "0 → 2 (2s¹2p¹)"], ["₅B (бор)", "Да", "1 → 3 (2s¹2p²)"], ["₆C (углерод)", "Да", "2 → 4 (2s¹2p³)"], ["₇N (азот)", "Нет (нет 2d)", "3 (не возбуждается)"], ["₈O (кислород)", "Нет (нет 2d)", "2 (не возбуждается)"], ["₉F (фтор)", "Нет (нет 2d)", "1 (не возбуждается)"], ["₁₅P (фосфор)", "Да", "3 → 5 (3s¹3p³3d¹)"], ["₁₆S (сера)", "Да", "2 → 4 → 6 (через 3d)"], ["₁₇Cl (хлор)", "Да", "1 → 3 → 5 → 7 (через 3d)"]], "rw": {"₇N (азот)": "На 2-м уровне нет 2d-подуровня и нет пустых 2p-клеток — возбуждение невозможно!", "₁₆S (сера)": "Две ступени возбуждения: 3s²3p³3d¹ (4 несп.) и 3s¹3p³3d² (6 несп.)."}}, {"id": "t_ions", "t": "Электронные конфигурации катионов и анионов", "k": "Ион", "km": "ионом", "ref": "07.12", "n": 1, "lv3": ["Fe^{2+}", "Fe^{3+}", "Cr^{3+}", "Cu^{+}", "Zn^{2+}", "Ga^{3+}", "Sc^{3+}"], "cols": [{"t": "Электронная конфигурация", "sk": "ions_noble", "n": 1, "q": "Какую электронную конфигурацию имеет ион {x}?", "m": "электронной конфигурацией", "mq": "Выберите {k} иона, имеющих конфигурацию «{v}»:"}, {"t": "Оболочка благородного газа?", "sk": "ions_noble", "n": 1, "q": "Имеет ли ион {x} электронную конфигурацию благородного (инертного) газа?", "m": "совпадением с конфигурацией благородного газа", "mq": "Выберите {k} иона, для которых совпадение с благородным газом — «{v}»:"}], "rows": [["O^{2−}", "1s²2s²2p⁶ ([Ne])", "Да (неон Ne)"], ["Na^{+}", "1s²2s²2p⁶ ([Ne])", "Да (неон Ne)"], ["S^{2−}", "1s²2s²2p⁶3s²3p⁶ ([Ar])", "Да (аргон Ar)"], ["Ca^{2+}", "1s²2s²2p⁶3s²3p⁶ ([Ar])", "Да (аргон Ar)"], ["Sc^{3+}", "1s²2s²2p⁶3s²3p⁶ ([Ar])", "Да (аргон Ar)"], ["Fe^{2+}", "[Ar]3d⁶", "Нет"], ["Fe^{3+}", "[Ar]3d⁵", "Нет"], ["Cr^{3+}", "[Ar]3d³", "Нет"], ["Cu^{+}", "[Ar]3d¹⁰", "Нет (28 e⁻ ≠ Ar)"], ["Zn^{2+}", "[Ar]3d¹⁰", "Нет (28 e⁻ ≠ Ar)"], ["Ga^{3+}", "[Ar]3d¹⁰", "Нет (28 e⁻ ≠ Ar)"]], "rw": {"Fe^{2+}": "Сначала уходят оба электрона с внешнего 4s², а 3d⁶ остаётся нетронутым.", "Zn^{2+}": "Ловушка на 100 баллов! [Ar]3d¹⁰ содержит 28 e⁻ — это НЕ конфигурация аргона (18 e⁻)."}}], "rx": [{"id": "rx_fe_fe2", "sk": "ions_noble", "ref": "07.7", "n": 1, "lvl": 2, "half": true, "l": ["Fe"], "r": ["Fe^{2+}", "e⁻"], "c": [1, 1, 2], "if": "образование катиона железа(II): уходят два электрона с внешнего 4s-подуровня", "why": "Нейтральный атом Fe ([Ar]3d⁶4s²) отдаёт оба 4s-электрона и превращается в Fe^{2+} ([Ar]3d⁶)."}, {"id": "rx_cr_cr3", "sk": "ions_noble", "ref": "07.15", "n": 1, "lvl": 3, "half": true, "l": ["Cr"], "r": ["Cr^{3+}", "e⁻"], "c": [1, 1, 3], "if": "образование катиона хрома(III): уходит 4s¹ и затем два 3d-электрона", "why": "Нейтральный атом Cr ([Ar]3d⁵4s¹) отдаёт 1 электрон с 4s и 2 электрона с 3d, получая конфигурацию Cr^{3+} ([Ar]3d³)."}, {"id": "rx_s_s2", "sk": "ions_noble", "ref": "07.15", "n": 1, "lvl": 1, "half": true, "l": ["S", "e⁻"], "r": ["S^{2−}"], "c": [1, 2, 1], "if": "образование сульфид-иона с конфигурацией аргона [Ar]", "why": "Атом серы ([Ne]3s²3p⁴) принимает 2 электрона на 3p-подуровень и завершает октет до [Ar]."}], "seq": [{"id": "sq_klechkovsky", "sk": "klechkovsky_spd", "ref": "03.5", "n": 1, "lvl": 2, "q": "Расположите подуровни в правильном порядке их заполнения электронами по правилу Клечковского (от меньшей энергии к большей):", "items": ["3s (n + l = 3 + 0 = 3)", "3p (n + l = 3 + 1 = 4, n = 3)", "4s (n + l = 4 + 0 = 4, n = 4)", "3d (n + l = 3 + 2 = 5, n = 3)", "4p (n + l = 4 + 1 = 5, n = 4)"], "why": "Сначала растёт сумма (n + l): 3 < 4 < 5; при равной сумме (3p и 4s дают 4; 3d и 4p дают 5) раньше заполняется подуровень с меньшим n."}, {"id": "sq_unpaired_order", "sk": "d_promotion", "ref": "04.11", "n": 1, "lvl": 3, "q": "Расположите атомы в порядке ВОЗРАСТАНИЯ числа неспаренных электронов в их основном состоянии (от 0 до 6):", "items": ["Zn ([Ar]3d¹⁰4s² — 0 неспаренных)", "Cu ([Ar]3d¹⁰4s¹ — 1 неспаренный)", "O (2s²2p⁴ — 2 неспаренных)", "N (2s²2p³ — 3 неспаренных)", "Fe ([Ar]3d⁶4s² — 4 неспаренных)", "Mn ([Ar]3d⁵4s² — 5 неспаренных)", "Cr ([Ar]3d⁵4s¹ — 6 неспаренных)"], "why": "Учитываем правило Хунда для p- и d-подуровней и провал электрона у Cu (1 неспаренный) и Cr (6 неспаренных)."}, {"id": "sq_cl_excitation", "sk": "excited_state", "ref": "06.12", "n": 1, "lvl": 3, "q": "Расположите состояния атома хлора (₁₇Cl) в порядке последовательного возбуждения — от основного к максимальному возбуждённому:", "items": ["3s²3p⁵ (основное состояние, 1 неспаренный)", "3s²3p⁴3d¹ (1-я ступень возбуждения, 3 неспаренных)", "3s²3p³3d² (2-я ступень возбуждения, 5 неспаренных)", "3s¹3p³3d³ (3-я ступень возбуждения, 7 неспаренных)"], "why": "На каждой ступени распадается одна пара (сначала две 3p-пары, затем 3s-пара), и число неспаренных растёт с шагом +2: 1 → 3 → 5 → 7."}, {"id": "sq_kim1_algo", "sk": "kim1_strategy", "ref": "08.8", "n": 1, "lvl": 2, "q": "Установите правильную последовательность шагов боевого алгоритма решения задания № 1 КИМ ЕГЭ-2027:", "items": ["Найти все 5 элементов в чёрно-белой таблице ФИПИ, подписать Z, период и подгруппу (А/Б)", "Выписать электронные конфигурации всех 5 элементов на черновике и сразу пометить Cr, Cu, He, Zn, N/O/F", "Подчеркнуть в условии все слова-переключатели (основное/возбуждённое, внешние/валентные/всего, атом/ион)", "Проверить каждый из 5 элементов по всем признакам условия и расставить «+» и «−»", "Убедиться, что плюсов ровно 2, перечитать условие с конца и записать две цифры в бланк"], "why": "Выписывание конфигураций до выбора ответа исключает 99% ошибок на скрытых переключателях."}], "facts": [{"id": "f_nuclei_pshe", "sk": "atom_pshe", "ref": "01.12", "n": 1, "lvl": 2, "t": "Ядро, изотопы и таблица ФИПИ", "s": [["В нейтральном атоме число протонов равно числу электронов и равно порядковому номеру элемента Z.", "В нейтральном атоме число нейтронов всегда равно порядковому номеру элемента Z.", "Порядковый номер Z определяет число протонов (и электронов), а число нейтронов равно A − Z и часто превышает Z."], ["У наиболее распространённого изотопа хлора (³⁵Cl) число протонов (17) не равно числу нейтронов (18).", "Поскольку Ar(Cl) = 35,45, у основного изотопа хлора 17 протонов и 19 нейтронов.", "Природный хлор состоит из ³⁵Cl (75%, 18 n) и ³⁷Cl (25%, 20 n); стабильного изотопа ³⁶Cl не существует."], ["Изотопы одного химического элемента имеют одинаковое число протонов в ядре, но разное число нейтронов.", "Изотопы одного элемента различаются числом протонов, но имеют одинаковое массовое число.", "Одинаковый заряд ядра Z определяет сам элемент; изотопы различаются именно числом нейтронов."], ["В чёрно-белой таблице ФИПИ элементы главных подгрупп (А) выровнены по тому же краю столбца, что и элементы 2–3 периодов.", "В таблице ФИПИ все элементы в левой половине таблицы относятся к главным подгруппам, а в правой — к побочным.", "В каждой группе 4–7 периодов ориентиром для главной подгруппы (А) служит выравнивание элементов 2–3 периодов."], ["У наиболее распространённых изотопов углерода (¹²C), азота (¹⁴N), кислорода (¹⁶O), магния (²⁴Mg), серы (³²S) и кальция (⁴⁰Ca) число протонов равно числу нейтронов.", "У наиболее распространённых изотопов натрия (²³Na), алюминия (²⁷Al) и фтора (¹⁹F) число протонов равно числу нейтронов.", "У ²³Na (11 p, 12 n), ²⁷Al (13 p, 14 n) и ¹⁹F (9 p, 10 n) нейтронов на один больше, чем протонов."]]}, {"id": "f_orbitals_spd", "sk": "klechkovsky_spd", "ref": "03.15", "n": 1, "lvl": 3, "t": "Орбитали, Клечковский, семейства и подсчёт электронов", "s": [["Гелий (₂He, 1s²) относится к s-элементам, несмотря на то что расположен в VIII группе таблицы Менделеева.", "Гелий (₂He) относится к p-элементам, так как стоит в одном столбце с неоном и аргоном.", "Семейство определяется последним заполняемым подуровнем (1s² → s-элемент)."], ["Исключительно s-электроны (и 0 p-электронов) содержатся только в атомах четырёх элементов: H, He, Li и Be.", "Только s-электроны содержатся в атомах всех элементов IA и IIA групп (включая Na, Mg, K, Ca).", "Уже начиная с бора (Z = 5) появляются 2p-электроны, поэтому у Na, Mg, K, Ca есть закрытый 2p⁶ (и 3p⁶)."], ["У p-элементов 4-го периода (Ga, Ge, As, Se, Br, Kr) в основном состоянии имеется полностью заполненный 3d¹⁰-подуровень.", "Полностью заполненный 3d-подуровень в 4-м периоде есть только у меди Cu и цинка Zn.", "После Zn (3d¹⁰4s²) начинает заполняться 4p-подуровень, а предвнешний 3d¹⁰ сохраняется у всех элементов Ga–Kr."], ["В основном состоянии атомов кислорода (₈O) и магния (₁₂Mg) общее число s-электронов равно общему числу p-электронов.", "В основном состоянии атома магния (₁₂Mg) вообще нет p-электронов, так как он s-элемент.", "У O (1s²2s²2p⁴) 4 s = 4 p; у Mg (1s²2s²2p⁶3s²) 6 s = 6 p (внутренний 2p⁶ обязательно учитывается!)."], ["На втором энергетическом уровне (n = 2) существует максимум 8 электронов и только два подуровня: 2s и 2p.", "На втором энергетическом уровне есть 2d-подуровень, который просто остаётся пустым в основном состоянии.", "По формуле 2n² при n = 2 максимум 8 электронов; d-подуровень появляется только с 3-го уровня (3d)."]]}, {"id": "f_d_promotion", "sk": "d_promotion", "ref": "04.19", "n": 1, "lvl": 3, "t": "d-элементы и провал электрона (Cr, Cu, Mo, Ag)", "s": [["У хрома (₂₄Cr: [Ar]3d⁵4s¹) в основном состоянии ровно 6 неспаренных электронов — это максимум среди элементов 1–4 периодов.", "У хрома (₂₄Cr) в основном состоянии 4 неспаренных электрона (3d⁴4s²).", "Из-за провала электрона с 4s на 3d неспаренными оказываются пять 3d-электронов и один 4s-электрон (5 + 1 = 6)."], ["Атомы хрома Cr и меди Cu в основном состоянии содержат ровно по 7 s-электронов во всём атоме — столько же, сколько калий K.", "Все d-элементы 4-го периода от скандия до цинка содержат ровно по 8 s-электронов.", "У Cr и Cu на 4s остался 1 электрон (1s²2s²3s²4s¹ = 7 s-e⁻), тогда как у остальных d-элементов 4-го периода их 8."], ["У меди (₂₉Cu: [Ar]3d¹⁰4s¹) на внешнем уровне 1 электрон и ровно 1 неспаренный электрон.", "У меди (₂₉Cu) 0 неспаренных электронов, так как её 3d-подуровень полностью заполнен.", "3d¹⁰ действительно спарен, но одиночный электрон на 4s¹ остаётся неспаренным."], ["В 5-м периоде провал электрона 5s → 4d происходит у молибдена (₄₂Mo: [Kr]4d⁵5s¹) и серебра (₄₇Ag: [Kr]4d¹⁰5s¹).", "Провал электрона встречается исключительно в 4-м периоде и никогда не наблюдается в 5-м периоде.", "Mo стоит под Cr (VIB), а Ag — под Cu (IB); оба повторяют устойчивые оболочки d⁵s¹ и d¹⁰s¹."], ["У марганца (₂₅Mn: [Ar]3d⁵4s²) провала электрона нет — на внешнем 4-м уровне у него 2 электрона и 5 неспаренных.", "У марганца (₂₅Mn) тоже происходит провал электрона, как у хрома.", "У Mn подуровень 3d⁵ уже наполовину заполнен, а 4s² полностью заполнен — переносить электрон невыгодно."]]}, {"id": "f_outer_val", "sk": "outer_valence", "ref": "05.16", "n": 1, "lvl": 3, "t": "Внешние vs валентные электроны и завершение уровня", "s": [["У всех d-элементов 4-го периода (Sc–Zn) на внешнем энергетическом уровне находится либо 1 (у Cr и Cu), либо 2 (у остальных) электрона.", "У марганца (VIIB) на внешнем энергетическом уровне находится 7 электронов.", "7 у марганца — это число ВАЛЕНТНЫХ электронов (3d⁵4s²), а на внешнем 4-м уровне их всего 2 (4s²)."], ["Атомы гелия (He), магния (Mg), железа (Fe) и цинка (Zn) имеют одинаковую электронную конфигурацию внешнего уровня вида ns².", "Гелий (1s²) не имеет одинаковой конфигурации внешнего уровня с магнием (3s²) и цинком (4s²).", "Запись 1s² полностью соответствует общему виду ns² при n = 1."], ["Атому водорода H (1s¹), как и атомам фтора F и хлора Cl, до завершения внешнего энергетического уровня недостаёт ровно 1 электрона.", "Атому водорода H до завершения внешнего уровня недостаёт 7 электронов (до октета).", "1-й уровень завершается дублетом 1s² (2 e⁻), поэтому водороду нужен всего 1 электрон."], ["У цинка (₃₀Zn: [Ar]3d¹⁰4s²) в школьной модели ЕГЭ число валентных электронов равно 2, так как закрытый 3d¹⁰ не участвует в связях.", "У цинка (₃₀Zn) 12 валентных электронов, как сумма 3d¹⁰ и 4s².", "Цинк проявляет единственную степень окисления +2, используя только пару 4s²."], ["У хрома (Cr) и серы (S) одинаковое число валентных электронов (по 6), но разное число внешних электронов (1 у Cr и 6 у S).", "Если у двух элементов одинаковое число валентных электронов, то у них обязательно одинаковое число внешних электронов.", "Это правило верно только для элементов главных подгрупп, но нарушается при сравнении s/p-элемента с d-элементом."]]}, {"id": "f_excited", "sk": "excited_state", "ref": "06.17", "n": 1, "lvl": 3, "t": "Основное и возбуждённое состояния атома", "s": [["Атомы азота (N), кислорода (O) и фтора (F) не способны переходить в возбуждённое состояние в пределах внешнего 2-го уровня.", "Атом азота в азотной кислоте HNO3 переходит в возбуждённое состояние с 5 неспаренными электронами.", "На 2-м уровне нет 2d-подуровня и пустых 2p-орбиталей; в HNO3 степень окисления N равна +5, а валентность — IV."], ["Углерод (₆C) и кремний (₁₄Si) в возбуждённом состоянии имеют одинаковую конфигурацию внешнего уровня ns¹np³ и по 4 неспаренных электрона.", "Углерод и кремний не могут переходить в возбуждённое состояние, так как в основном состоянии у них уже есть неспаренные электроны.", "У обоих есть пара ns² и свободная np-орбиталь → распаривание даёт ns¹np³ (4 неспаренных)."], ["Сера (₁₆S) способна давать два возбуждённых состояния (4 и 6 неспаренных электронов), а кислород (₈O) — ни одного.", "Кислород и сера стоят в одной группе VIA, поэтому оба могут иметь 6 неспаренных электронов в возбуждённом состоянии.", "У серы на 3-м уровне есть пустой 3d-подуровень, а у кислорода на 2-м уровне 2d-подуровня нет."], ["Максимальное число неспаренных электронов в возбуждённом состоянии хлора (₁₇Cl) равно 7 (конфигурация 3s¹3p³3d³).", "У хлора в возбуждённом состоянии может быть 2, 4 или 6 неспаренных электронов.", "В основном состоянии у Cl 1 неспаренный; каждая ступень возбуждения добавляет +2: 1 → 3 → 5 → 7 (только нечётные!)."], ["Атомы щелочных металлов (Li, Na, K) не переходят в возбуждённое состояние по механизму распаривания, так как на их внешнем уровне нет электронной пары.", "Натрий (3s¹) может перейти в возбуждённое состояние с 3 неспаренными электронами за счёт 3p-подуровня.", "На 3s¹ всего один электрон — распаривать нечего (в ЕГЭ учитывается только распаривание пар внешнего слоя)."]]}, {"id": "f_ions_terms", "sk": "ions_noble", "ref": "07.13", "n": 1, "lvl": 3, "t": "Конфигурации ионов и тонкие термины КИМ № 1", "s": [["При ионизации любого d-металла 4-го периода электроны сначала удаляются с внешнего 4s-подуровня, и только затем с 3d.", "Поскольку 3d заполняется последним, при образовании катиона Fe^{2+} электроны сначала уходят с 3d.", "Уход 4s раньше 3d даёт Fe^{2+} = [Ar]3d⁶ (а не [Ar]3d⁴4s²)."], ["Катионы Cu^{+}, Zn^{2+} и Ga^{3+} имеют одинаковую конфигурацию [Ar]3d¹⁰ (28 e⁻), но НЕ имеют конфигурации благородного газа.", "Поскольку у Zn^{2+} ([Ar]3d¹⁰) 3-й уровень полностью заполнен, он имеет конфигурацию инертного газа аргона.", "У аргона 18 электронов (3s²3p⁶), а у [Ar]3d¹⁰ — 28 электронов (оболочка благородного газа всегда ns²np⁶ или 1s²)."], ["Катион скандия Sc^{3+} и сульфид-ион S^{2−} изоэлектронны и оба имеют электронную конфигурацию аргона [Ar].", "Ни один d-элемент не может образовать катион с электронной конфигурацией аргона.", "У Sc ([Ar]3d¹4s²) после отдачи всех трёх валентных электронов остаётся чистая оболочка [Ar]."], ["У атомов Ar, K, Ca и Sc–Ni полностью заполнены только 2 энергетических уровня (1-й и 2-й), так как 3-й уровень вмещает 18 электронов.", "У атома калия K (1s²2s²2p⁶3s²3p⁶4s¹) полностью заполнены 3 энергетических уровня.", "На 3-м уровне у K только 8 электронов из 18 возможных (3d пуст); полностью 3-й уровень заполняется лишь начиная с Cu и Zn."], ["В катионе железа(III) Fe^{3+} ([Ar]3d⁵) 5 неспаренных электронов — столько же, сколько в нейтральном атоме марганца Mn.", "В катионе Fe^{3+} 3 неспаренных электрона, так как он отдал 3 электрона с 3d⁶.", "У Fe ([Ar]3d⁶4s²) уходят два электрона с 4s² и один с 3d⁶ → остаётся 3d⁵ (5 неспаренных)."]]}], "calc": [{"id": "c_neutrons", "sk": "atom_pshe", "ref": "01.9", "n": 1, "lvl": 1, "v": {"_": [{"sym": "¹⁶O", "A": 16, "Z": 8}, {"sym": "²³Na", "A": 23, "Z": 11}, {"sym": "²⁷Al", "A": 27, "Z": 13}, {"sym": "³¹P", "A": 31, "Z": 15}, {"sym": "³⁵Cl", "A": 35, "Z": 17}, {"sym": "³⁷Cl", "A": 37, "Z": 17}, {"sym": "⁵⁶Fe", "A": 56, "Z": 26}, {"sym": "⁶⁵Zn", "A": 65, "Z": 30}]}, "q": "Сколько нейтронов содержится в ядре изотопа {=sym} (порядковый номер Z = {=Z}, массовое число A = {=A})?", "a": "A - Z", "dp": 0, "unit": "нейтронов", "ex": "Число нейтронов N = A − Z = {=A} − {=Z} = {=A-Z}."}, {"id": "c_max_electrons", "sk": "orbitals_hund", "ref": "02.4", "n": 1, "lvl": 1, "v": {"n": [1, 2, 3, 4]}, "q": "Какое МАКСИМАЛЬНОЕ число электронов может вместить энергетический уровень с номером n = {=n} (по формуле 2n²)?", "a": "2 * n * n", "dp": 0, "unit": "электронов", "ex": "Максимальная ёмкость n-го энергетического уровня равна 2n² = 2 · {=n}² = {=2*n*n} электронов."}, {"id": "c_ion_electrons", "sk": "ions_noble", "ref": "07.3", "n": 1, "lvl": 2, "v": {"_": [{"ion": "Na^{+}", "Z": 11, "q": 1}, {"ion": "O^{2−}", "Z": 8, "q": -2}, {"ion": "S^{2−}", "Z": 16, "q": -2}, {"ion": "Sc^{3+}", "Z": 21, "q": 3}, {"ion": "Cr^{3+}", "Z": 24, "q": 3}, {"ion": "Fe^{2+}", "Z": 26, "q": 2}, {"ion": "Fe^{3+}", "Z": 26, "q": 3}, {"ion": "Zn^{2+}", "Z": 30, "q": 2}]}, "q": "Сколько ВСЕГО электронов содержится в электронной оболочке иона {=ion} (порядковый номер элемента Z = {=Z})?", "a": "Z - q", "dp": 0, "unit": "электронов", "ex": "При образовании катиона (заряд +k) отнимаем k электронов, при образовании аниона (заряд −m) прибавляем m: N(e⁻) = {=Z} − ({=q}) = {=Z-q}."}], "tasks": [{"id": "t01_demo2027", "type": "multi", "sk": "klechkovsky_spd", "ref": "03.17", "n": 1, "lvl": 3, "q": "[ДЕМО-2027 ФИПИ] Определите, атомы каких двух из указанных в ряду элементов в основном состоянии содержат такое же число s-электронов, как и катион натрия Na^{+}.", "o": ["O", "F", "Al", "Si", "Li"], "a": [0, 1], "ex": "У катиона Na^{+} (1s²2s²2p⁶) всего 2 + 2 = 4 s-электрона. Считаем все s-электроны в ряду: 1) O (1s²2s²2p⁴) → 4 (ДА); 2) F (1s²2s²2p⁵) → 4 (ДА); 3) Al (1s²2s²2p⁶3s²3p¹) → 6; 4) Si (1s²2s²2p⁶3s²3p²) → 6; 5) Li (1s²2s¹) → 3. Ответ: 12."}, {"id": "t02_protons_neutrons", "type": "multi", "sk": "atom_pshe", "ref": "01.12", "n": 1, "lvl": 2, "q": "Определите, у наиболее распространённых изотопов каких двух из указанных элементов число протонов в ядре равно числу нейтронов.", "o": ["Cl", "Ca", "Al", "S", "F"], "a": [1, 3], "ex": "Сравниваем Z и N = A − Z: 1) ³⁵Cl: 17 p, 18 n (ловушка Ar = 35,45!); 2) ⁴⁰Ca: 20 p = 20 n (ДА); 3) ²⁷Al: 13 p, 14 n; 4) ³²S: 16 p = 16 n (ДА); 5) ¹⁹F: 9 p, 10 n. Ответ: 24."}, {"id": "t03_unpaired_2", "type": "multi", "sk": "orbitals_hund", "ref": "02.16", "n": 1, "lvl": 2, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии содержат ровно 2 неспаренных электрона.", "o": ["Be", "C", "N", "S", "Mg"], "a": [1, 3], "ex": "1) Be (2s²) → 0; 2) C (2s²2p²) → 2 по правилу Хунда (ДА); 3) N (2s²2p³) → 3; 4) S (3s²3p⁴) → 2 (↑↓ ↑ ↑) (ДА); 5) Mg (3s²) → 0. Ответ: 24."}, {"id": "t04_unpaired_0", "type": "multi", "sk": "orbitals_hund", "ref": "02.18", "n": 1, "lvl": 2, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии НЕ содержат неспаренных электронов.", "o": ["Cu", "Zn", "He", "Cr", "C"], "a": [1, 2], "ex": "1) Cu ([Ar]3d¹⁰4s¹) → 1 неспаренный на 4s¹; 2) Zn ([Ar]3d¹⁰4s²) → 0 (ДА); 3) He (1s²) → 0 (ДА); 4) Cr ([Ar]3d⁵4s¹) → 6; 5) C (2s²2p²) → 2. Ответ: 23."}, {"id": "t05_s_equals_p", "type": "multi", "sk": "klechkovsky_spd", "ref": "03.18", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии содержат одинаковое число s-электронов и p-электронов (во всём атоме).", "o": ["Be", "C", "O", "Mg", "Si"], "a": [2, 3], "ex": "Суммируем по всем уровням: 1) Be (1s²2s²): 4 s, 0 p; 2) C (1s²2s²2p²): 4 s, 2 p; 3) O (1s²2s²2p⁴): 4 s = 4 p (ДА); 4) Mg (1s²2s²2p⁶3s²): 6 s = 6 p (ДА); 5) Si (1s²2s²2p⁶3s²3p²): 6 s, 8 p. Ответ: 34."}, {"id": "t06_only_s_electrons", "type": "multi", "sk": "klechkovsky_spd", "ref": "03.18", "n": 1, "lvl": 2, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии НЕ содержат p-электронов (содержат только s-электроны).", "o": ["B", "He", "Na", "Be", "Mg"], "a": [1, 3], "ex": "Только s-электроны имеют строго 4 элемента (H, He, Li, Be): 1) B (2p¹) — есть p; 2) He (1s²) — только s (ДА); 3) Na (2p⁶) — есть p; 4) Be (1s²2s²) — только s (ДА); 5) Mg (2p⁶) — есть p. Ответ: 24."}, {"id": "t07_full_3d10", "type": "multi", "sk": "klechkovsky_spd", "ref": "03.15", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии содержат полностью заполненный d-подуровень.", "o": ["Fe", "Br", "Cr", "Cu", "K"], "a": [1, 3], "ex": "1) Fe ([Ar]3d⁶4s²) — 3d недозаполнен; 2) Br ([Ar]3d¹⁰4s²4p⁵) — есть закрытый 3d¹⁰ (ДА); 3) Cr ([Ar]3d⁵4s¹) — наполовину заполнен; 4) Cu ([Ar]3d¹⁰4s¹) — из-за провала 3d¹⁰ полностью заполнен (ДА); 5) K ([Ar]4s¹) — 3d пуст. Ответ: 24."}, {"id": "t08_promotion_outer_1", "type": "multi", "sk": "d_promotion", "ref": "04.20", "n": 1, "lvl": 2, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии имеют на внешнем энергетическом уровне ровно 1 электрон.", "o": ["K", "Be", "Cu", "Al", "Mn"], "a": [0, 2], "ex": "1) K ([Ar]4s¹) → 1 внешний (ДА); 2) Be (2s²) → 2; 3) Cu ([Ar]3d¹⁰4s¹) → провал! 1 внешний (ДА); 4) Al (3s²3p¹) → 3 внешних; 5) Mn ([Ar]3d⁵4s²) → 2 внешних. Ответ: 13."}, {"id": "t09_promotion_7s", "type": "multi", "sk": "d_promotion", "ref": "04.19", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии содержат ровно 7 s-электронов во всём атоме.", "o": ["Ca", "Cr", "Mn", "Cu", "Zn"], "a": [1, 3], "ex": "В 4-м периоде сумма 1s² + 2s² + 3s² = 6 s-электронов. Чтобы получить 7, на 4s должен быть ровно 1 электрон (4s¹): это K, Cr ([Ar]3d⁵4s¹) и Cu ([Ar]3d¹⁰4s¹). У Ca, Mn, Zn по 8 s-электронов. Ответ: 24."}, {"id": "t10_same_outer_ns2", "type": "multi", "sk": "outer_valence", "ref": "05.11", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии имеют электронную конфигурацию внешнего энергетического уровня ns².", "o": ["He", "Cr", "Fe", "Cu", "N"], "a": [0, 2], "ex": "1) He (1s² → ns²) (ДА); 2) Cr (4s¹ → ns¹); 3) Fe ([Ar]3d⁶4s² → ns²) (ДА); 4) Cu (4s¹ → ns¹); 5) N (2s²2p³). Ответ: 13."}, {"id": "t11_valence_6", "type": "multi", "sk": "outer_valence", "ref": "05.15", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии содержат ровно 6 валентных электронов.", "o": ["Cr", "S", "Mn", "Mg", "Zn"], "a": [0, 1], "ex": "1) Cr ([Ar]3d⁵4s¹): валентные 3d⁵ + 4s¹ = 6 (ДА); 2) S ([Ne]3s²3p⁴): 2 + 4 = 6 (ДА); 3) Mn (3d⁵4s²): 7; 4) Mg (3s²): 2; 5) Zn ([Ar]3d¹⁰4s²): 3d¹⁰ не валентен → 2. Ответ: 12."}, {"id": "t12_outer_less_valence", "type": "multi", "sk": "outer_valence", "ref": "05.16", "n": 1, "lvl": 3, "q": "Определите, у атомов каких двух из указанных элементов в основном состоянии число внешних электронов МЕНЬШЕ числа валентных электронов.", "o": ["P", "Fe", "Zn", "Mn", "Se"], "a": [1, 3], "ex": "Число внешних меньше числа валентных у переходных d-элементов Sc–Cu: 1) P (5 = 5); 2) Fe (2 внешних < 8 валентных, ДА); 3) Zn (2 внешних = 2 валентных — ловушка!); 4) Mn (2 внешних < 7 валентных, ДА); 5) Se (6 = 6). Ответ: 24."}, {"id": "t13_missing_1_electron", "type": "multi", "sk": "outer_valence", "ref": "05.13", "n": 1, "lvl": 3, "q": "Определите, атомам каких двух из указанных элементов в основном состоянии до завершения внешнего энергетического уровня недостаёт ровно 1 электрона.", "o": ["H", "Li", "O", "Cl", "N"], "a": [0, 3], "ex": "1) H (1s¹): до завершения 1-го уровня (дублета 1s²) не хватает 1 e⁻ (ДА); 2) Li (2s¹): до октета не хватает 7 e⁻; 3) O (2s²2p⁴): не хватает 2 e⁻; 4) Cl (3s²3p⁵): до октета не хватает 1 e⁻ (ДА); 5) N (2s²2p³): не хватает 3 e⁻. Ответ: 14."}, {"id": "t14_no_excitation", "type": "multi", "sk": "excited_state", "ref": "06.16", "n": 1, "lvl": 2, "q": "Определите, атомы каких двух из указанных элементов НЕ способны переходить в возбуждённое состояние в пределах внешнего энергетического уровня.", "o": ["C", "N", "P", "O", "S"], "a": [1, 3], "ex": "На 2-м уровне нет 2d-подуровня и у N (2s²2p³), O (2s²2p⁴) нет пустых 2p-орбиталей → N и O не возбуждаются (ДА). У C есть пустая 2p-орбиталь, у P и S есть пустой 3d-подуровень. Ответ: 24."}, {"id": "t15_excited_4_unpaired", "type": "multi", "sk": "excited_state", "ref": "06.17", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в возбуждённом состоянии могут иметь электронную конфигурацию внешнего уровня ns¹np³.", "o": ["C", "S", "Si", "O", "P"], "a": [0, 2], "ex": "Конфигурацию ns¹np³ (4 неспаренных без участия d-подуровня) при возбуждении из ns²np² получают элементы IVA группы: 1) C (2s¹2p³, ДА); 2) S (3s²3p³3d¹ — есть d!); 3) Si (3s¹3p³, ДА); 4) O (не возбуждается); 5) P (3s¹3p³3d¹ — есть d!). Ответ: 13."}, {"id": "t16_excited_max_5_7", "type": "multi", "sk": "excited_state", "ref": "06.12", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в возбуждённом состоянии могут иметь ровно 5 неспаренных электронов.", "o": ["N", "P", "S", "Cl", "C"], "a": [1, 3], "ex": "1) N (3, не возбуждается); 2) P (3s²3p³ → 3s¹3p³3d¹ = 5 неспаренных, ДА); 3) S (2 → 4 → 6 — только чётные!); 4) Cl (1 → 3 → 5 → 7, 2-я ступень 3s²3p³3d² = 5 неспаренных, ДА); 5) C (2 → 4). Ответ: 24."}, {"id": "t17_ions_argon", "type": "multi", "sk": "ions_noble", "ref": "07.13", "n": 1, "lvl": 3, "q": "Определите, какие два из указанных элементов образуют катион в характерной (высшей) степени окисления (Sc^{3+}, Zn^{2+}, Ca^{2+}, Ga^{3+}, Fe^{3+}), имеющий электронную конфигурацию благородного газа аргона.", "o": ["Sc", "Zn", "Ca", "Ga", "Fe"], "a": [0, 2], "ex": "1) Sc^{3+} = [Ar] (ДА); 2) Zn^{2+} = [Ar]3d¹⁰ (28 e⁻ — НЕ аргон!); 3) Ca^{2+} = [Ar] (ДА); 4) Ga^{3+} = [Ar]3d¹⁰ (НЕ аргон!); 5) Fe^{3+} = [Ar]3d⁵ (НЕ аргон). Ответ: 13."}, {"id": "t18_ions_d_unpaired", "type": "multi", "sk": "ions_noble", "ref": "07.15", "n": 1, "lvl": 3, "q": "Определите, какие два из указанных ионов имеют одинаковое число неспаренных электронов — ровно 5.", "o": ["Fe^{2+}", "Fe^{3+}", "Mn^{2+}", "Cr^{3+}", "Zn^{2+}"], "a": [1, 2], "ex": "Помним правило: у d-металлов сначала уходит 4s! 1) Fe^{2+} = [Ar]3d⁶ (4 несп.); 2) Fe^{3+} = [Ar]3d⁵ (5 несп., ДА); 3) Mn^{2+} = [Ar]3d⁵ (5 несп., ДА); 4) Cr^{3+} = [Ar]3d³ (3 несп.); 5) Zn^{2+} = [Ar]3d¹⁰ (0 несп.). Ответ: 23."}, {"id": "t19_filled_levels_3", "type": "multi", "sk": "kim1_strategy", "ref": "08.11", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии содержат ровно 3 ПОЛНОСТЬЮ ЗАПОЛНЕННЫХ энергетических уровня (по формуле 2n²).", "o": ["Ar", "K", "Cu", "Fe", "Br"], "a": [2, 4], "ex": "3-й уровень (18 e⁻ = 3s²3p⁶3d¹⁰) полностью заполнен только начиная с Cu и Zn! 1) Ar (2-й заполнен, 3d пуст → 2 уровня); 2) K (3d пуст → 2 уровня); 3) Cu (1-й: 2, 2-й: 8, 3-й: 18, 4-й: 1 → ровно 3 заполненных, ДА); 4) Fe (3d⁶ → 2 уровня); 5) Br (1-й: 2, 2-й: 8, 3-й: 18, 4-й: 7 → ровно 3 заполненных, ДА). Ответ: 35."}, {"id": "t20_combined_2cond", "type": "multi", "sk": "kim1_strategy", "ref": "08.10", "n": 1, "lvl": 3, "q": "Определите, атомы каких двух из указанных элементов в основном состоянии имеют ровно 1 электрон на внешнем уровне И относятся к d-элементам (учтите элементы 5-го периода).", "o": ["K", "Cr", "Zn", "Ag", "Rb"], "a": [1, 3], "ex": "Фильтр 1 (1 внешний электрон): подходят K (4s¹), Cr (4s¹), Ag (5s¹), Rb (5s¹); Zn (4s²) вычёркиваем. Фильтр 2 (d-элементы): K и Rb — s-элементы, остаются Cr ([Ar]3d⁵4s¹) и Ag ([Kr]4d¹⁰5s¹). Ответ: 24."}], "subjectSlug": "chemistry", "_kim": {"1": {"b": 1, "l": "Б"}}, "_kon": {"01": {"t": "Модуль 01. Атом, ядро и чёрно-белая таблица ФИПИ", "x": "Всё, что нужно для старта в задании № 1, уже напечатано в таблице Менделеева. **Порядковый номер Z** равен заряду ядра, числу протонов и числу электронов в нейтральном атоме, а **главную и побочную подгруппы** в чёрно-белом бланке ФИПИ выдаёт выравнивание символа элемента внутри ячейки."}, "01.1": {"t": "Модуль 01 · Главная мысль.", "x": "Всё, что нужно для старта в задании № 1, уже напечатано в таблице Менделеева. **Порядковый номер Z** равен заряду ядра, числу протонов и числу электронов в нейтральном атоме, а **главную и побочную подгруппы** в чёрно-белом бланке ФИПИ выдаёт выравнивание символа элемента внутри ячейки."}, "01.6": {"t": "Модуль 01 · 1. Из чего устроен атом: ядро и электронная оболочка", "x": "• **Протон** — p⁺; +1; 1; В ядре; равно [[Порядковый номер Z|порядковому номеру Z]]\n• **Нейтрон** — n⁰; 0; 1; В ядре; N = A − Z (для конкретного изотопа)\n• **Электрон** — e⁻; −1; ≈ 0 (1/1836); В оболочке; в нейтральном атоме равно Z"}, "01.9": {"t": "Модуль 01 · 2. Массовое число, изотопы и загадка хлора 35,5", "x": "Сумма протонов и нейтронов в ядре конкретного атома называется [[Массовое число A|массовым числом A]]: A = Z + N. Отсюда число нейтронов находится вычитанием: N = A − Z. Например, у наиболее распространённого атома алюминия ²⁷Al порядковый номер Z = 13, значит в ядре 13 протонов и 27 − 13 = 14 нейтронов."}, "01.12": {"t": "Модуль 01 · Ловушка ЕГЭ: округление Ar и изотопы хлора", "x": "В задании № 1 встречается вопрос: «У наиболее распространённых изотопов каких элементов число протонов равно числу нейтронов?». Среди первых 20 элементов равенство p = n выполняется ровно у девяти основных изотопов: ⁴He (2=2), ¹²C (6=6), ¹⁴N (7=7), ¹⁶O (8=8), ²⁰Ne (10=10), ²⁴Mg (12=12), ²⁸Si (14=14), ³²S (16=16), ⁴⁰Ca (20=20). У протия ¹H вообще 0 нейтронов (1p, 0n), а у ⁷Li, ⁹Be, ¹¹B, ¹⁹F, ²³Na, ²⁷Al, ³¹P, ³⁵Cl, ⁴⁰Ar, ³⁹K число нейтронов больше числа протонов. Не округляй Ar(Cl) = 35,45 до 36 — у хлора нет стабильного изотопа с 19 нейтронами, его основной изотоп ³⁵Cl (17 протонов и 18 нейтронов)."}, "02": {"t": "Модуль 02. Энергетические уровни, орбитали, принцип Паули и правило Хунда", "x": "Электронная оболочка устроена как многоэтажный дом: **номер периода = число уровней (этажей n)**, на каждом уровне есть **подуровни (s, p, d, f)**, а внутри них — **орбитали (комнаты-ячейки)**. В одну ячейку помещается не больше двух электронов с противоположными спинами (Паули), а пустые ячейки одного подуровня сначала заселяются по одному (Хунд)."}, "02.1": {"t": "Модуль 02 · Главная мысль.", "x": "Электронная оболочка устроена как многоэтажный дом: **номер периода = число уровней (этажей n)**, на каждом уровне есть **подуровни (s, p, d, f)**, а внутри них — **орбитали (комнаты-ячейки)**. В одну ячейку помещается не больше двух электронов с противоположными спинами (Паули), а пустые ячейки одного подуровня сначала заселяются по одному (Хунд)."}, "02.4": {"t": "Модуль 02 · 1. Энергетические уровни и формула 2n²", "x": "В Периодической системе число заполняемых энергетических уровней атома равно **номеру периода**: у лития (2-й период) их два, у серы (3-й период) — три, у железа (4-й период) — четыре. Максимальное число электронов, которое вообще может вместить уровень с номером n, подчиняется формуле N_{max} = 2n²:"}, "02.16": {"t": "Модуль 02 · 4. Разбор вслух: считаем неспаренные электроны в основном состоянии", "x": "**Задача:** Определи число неспаренных электронов в основном состоянии у ₄Be, ₆C, ₇N, ₈O и ₁₂Mg.\n**Шаг 2.** **Бериллий (₄Be) и магний (₁₂Mg):** у Be четыре электрона: 1s² (пара ↑↓) и 2s² (пара ↑↓). Все клетки заполнены парами → **0 неспаренных электронов**. Точно так же у Mg (1s²2s²2p⁶3s²), He, Ne, Ar, Ca, Zn — все электроны спарены (**0 неспаренных**).\n**Шаг 3.** **Углерод (₆C):** 1s²2s²2p². Внутренние 1s² и 2s² полностью спарены. Остаются 2 электрона на трёх клетках 2p. По правилу Хунда они садятся в две разные клетки (↑  ↑  [ ]), не образуя пару → **2 неспаренных электрона**.\n**Шаг 4.** **Азот (₇N):** 1s²2s²2p³. Три 2p-электрона занимают все три клетки по одному (↑  ↑  ↑) → **3 неспаренных электрона** (максимум для p-подуровня).…"}, "02.18": {"t": "Модуль 02 · Мост к КИМ (№ 1 КИМ)", "x": "**Как спрашивают:** «Определите, атомы каких из указанных элементов в основном состоянии содержат ровно 2 (или 3, 1, 0) неспаренных электрона» или «не содержат неспаренных электронов».\n**На чём ловят:** Считай неспаренные только на **недозаполненном** подуровне (закрытые s², p⁶, d¹⁰ всегда дают 0). Но для d-элементов с провалом (Cr, Cu) обязательно проверь оба подуровня 3d и 4s — об этом подробно в модуле 04!\n**Как читать:** Для быстрой проверки p-элементов используй симметрию: p¹ → 1, p² → 2, p³ → 3, p⁴ → 2, p⁵ → 1, p⁶ → 0. Для d-подуровня та же горка до 5: d¹ → 1, d² → 2, d³ → 3, d⁴ → 4, d⁵ → 5, d⁶ → 4, d⁷ → 3, d⁸ → 2, d⁹ → 1, d¹⁰ → 0."}, "03": {"t": "Модуль 03. Правило Клечковского, семейства s, p, d и подсчёт электронов", "x": "Подуровни заполняются не строго по номерам слоёв, а по возрастанию энергии — по **двухчастному правилу Клечковского (n + l)**. Из-за этого **4s заполняется раньше 3d**, а тип элемента (s, p или d) определяется тем подуровнем, который заполняется **последним**."}, "03.1": {"t": "Модуль 03 · Главная мысль.", "x": "Подуровни заполняются не строго по номерам слоёв, а по возрастанию энергии — по **двухчастному правилу Клечковского (n + l)**. Из-за этого **4s заполняется раньше 3d**, а тип элемента (s, p или d) определяется тем подуровнем, который заполняется **последним**."}, "03.5": {"t": "Модуль 03 · 1. Правило Клечковского: почему 4s опережает 3d", "x": "1. **Часть 1:** подуровни заполняются в порядке возрастания суммы **n + l**.\n2. **Часть 2:** если у двух подуровней суммы n + l **одинаковы**, то раньше заполняется подуровень с **меньшим n**."}, "03.15": {"t": "Модуль 03 · Ловушка ЕГЭ: He — s-элемент, а у Ga–Kr есть 3d¹⁰", "x": "Две главные ловушки семейств: во-первых, **гелий (₂He)** никогда не относят к p-элементам — его конфигурация 1s², у него вообще нет p-электронов, он s-элемент. Во-вторых, у p-элементов 4-го периода (**Ga, Ge, As, Se, Br, Kr**) конфигурация имеет вид [Ar]3d¹⁰4s²4p^k, поэтому на вопрос «у каких элементов есть полностью заполненный d-подуровень?» подходят не только Cu и Zn, но и Ga–Kr!"}, "03.17": {"t": "Модуль 03 · 4. Разбор вслух: конфигурации и задача № 1 из ДЕМО-2027", "x": "**Пример А (построение по Клечковскому):** Составим конфигурации ₁₉K, ₂₂Ti, ₃₅Br и элемента 5-го периода ₅₃I. У ₁₉K после аргона (18 e⁻) 19-й электрон идёт на 4s: 1s²2s²2p⁶3s²3p⁶4s¹ ([Ar]4s¹, s-элемент). У ₂₂Ti после 4s² (20 e⁻) два электрона идут на 3d: 1s²2s²2p⁶3s²3p⁶3d²4s² ([Ar]3d²4s², d-элемент). У ₃₅Br заполняется 3d¹⁰ и пять электронов идут на 4p: 1s²2s²2p⁶3s²3p⁶3d¹⁰4s²4p⁵ ([Ar]3d¹⁰4s²4p⁵, p-элемент с закрытым 3d¹⁰). Дальше цепочка продолжается 4p → 5s → 4d → 5p → 6s, поэтому у иода ₅₃I конфигурация [Kr]4d¹⁰5s²5p⁵ — у него сразу 20 d-электронов (3d¹⁰ + 4d¹⁰).\n**Пример Б (реальное задание № 1 из ДЕМО-2027 ФИПИ):** Дан ряд элементов: 1) O   2) F   3) Al   4) Si   5) Li. *«Определите, атомы каких двух из указанных в ряду элементов в основном состоянии содержат такое же число s-электронов, как и катион натрия.»*…"}, "03.18": {"t": "Модуль 03 · Мост к КИМ (№ 1 КИМ)", "x": "**Как спрашивают:** «Содержат одинаковое число s- (или p-, d-) электронов», «число p-электронов равно числу s-электронов», «число p-электронов в два раза больше числа s-электронов».\n**На чём ловят:** Если в условии **не сказано** «на внешнем уровне», то считают **все** s- или p-электроны **во всём атоме**! Например, у ₁₂Mg (1s²2s²2p⁶3s²) всего 6 s-электронов и 6 p-электронов (6 = 6), как и у ₈O (1s²2s²2p⁴: 4 = 4). А на вопрос «содержат **только s-электроны** / не содержат p-электронов» подходят строго четыре элемента всей таблицы: **H, He, Li, Be**!\n**Как читать:** Чтобы не сбиться при суммировании, всегда выписывай полную (не сокращённую!) конфигурацию для элементов 1–3 периодов и отдельно подчёркивай все s одной чертой, а все p — волнистой."}, "04": {"t": "Модуль 04. d-элементы 4-го периода и провал электрона (Cr, Cu)", "x": "У десяти d-элементов 4-го периода (₂₁Sc–₃₀Zn) заполняется предвнешний 3d-подуровень при уже занятом внешнем 4s. У восьми из них внешний слой — 4s², а у двух — **хрома (₂₄Cr: [Ar]3d⁵4s¹)** и **меди (₂₉Cu: [Ar]3d¹⁰4s¹)** — происходит **провал электрона** с 4s на 3d ради повышенной устойчивости полузаполненного (3d⁵) или полностью заполненного (3d¹⁰) подуровня."}, "04.1": {"t": "Модуль 04 · Главная мысль.", "x": "У десяти d-элементов 4-го периода (₂₁Sc–₃₀Zn) заполняется предвнешний 3d-подуровень при уже занятом внешнем 4s. У восьми из них внешний слой — 4s², а у двух — **хрома (₂₄Cr: [Ar]3d⁵4s¹)** и **меди (₂₉Cu: [Ar]3d¹⁰4s¹)** — происходит **провал электрона** с 4s на 3d ради повышенной устойчивости полузаполненного (3d⁵) или полностью заполненного (3d¹⁰) подуровня."}, "04.11": {"t": "Модуль 04 · 3. Полная таблица всех десяти d-элементов 4-го периода", "x": "• **₂₁Sc** — [Ar]3d¹4s²; 2; 1; Начало 3d-ряда\n• **₂₂Ti** — [Ar]3d²4s²; 2; 2; Норма\n• **₂₃V** — [Ar]3d³4s²; 2; 3; Норма\n• ****₂₄Cr**** — **[Ar]3d⁵4s¹**; **1**; **6**; **Провал электрона (3d⁵4s¹)!**\n• **₂₅Mn** — [Ar]3d⁵4s²; 2; 5; Устойчивый 3d⁵ + пара 4s²\n• **₂₆Fe** — [Ar]3d⁶4s²; 2; 4; Началось спаривание в 3d\n• **₂₇Co** — [Ar]3d⁷4s²; 2; 3; Норма\n• **₂₈Ni** — [Ar]3d⁸4s²; 2; 2; Норма\n• ****₂₉Cu**** — **[Ar]3d¹⁰4s¹**; **1**; **1**; **Провал электрона (3d¹⁰4s¹)!**\n• **₃₀Zn** — [Ar]3d¹⁰4s²; 2; 0; Все электроны спарены (0)"}, "04.19": {"t": "Модуль 04 · Ловушка ЕГЭ: провал меняет даже сумму s-электронов!", "x": "Обрати внимание на скрытую ловушку с **числом s-электронов у Cr и Cu**: из-за провала у них на 4s остаётся 1 электрон, поэтому суммарно в атоме у них **7 s-электронов** (1s²2s²3s²4s¹) — ровно столько же, сколько у калия (₁₉K)! Если забыть провал, получишь ошибочные 8 s-электронов."}, "04.20": {"t": "Модуль 04 · Мост к КИМ (№ 1 КИМ)", "x": "**Как спрашивают:** «На внешнем уровне содержится 1 электрон» (в ряду с Li/Na/K и Cr/Cu), «содержат 6 неспаренных электронов», «содержат одинаковое число s-электронов» (в паре K и Cr/Cu).\n**На чём ловят:** Как только видишь в ряду из пяти элементов **Cr или Cu** — сразу мысленно ставь над ними восклицательный знак и пиши 3d⁵4s¹ и 3d¹⁰4s¹. В 9 случаях из 10 составители добавили их в ряд именно ради проверки провала!\n**Как читать:** Помни тройку-антипод: у Cr **1** внешний, **6** неспаренных, **7** всего s-электронов; у Cu **1** внешний, **1** неспаренный, **7** всего s-электронов."}, "05": {"t": "Модуль 05. Внешние, предвнешние и валентные электроны", "x": "**Внешние электроны** — это строго электроны самого последнего слоя (max n). **Валентные электроны** — это электроны, участвующие в образовании химических связей: для s- и p-элементов они **совпадают с внешними** (ns + np), а для d-элементов (Sc–Cu) включают ещё и предвнешний d-подуровень (ns + (n−1)d), кроме стабильного 3d¹⁰ у цинка."}, "05.1": {"t": "Модуль 05 · Главная мысль.", "x": "**Внешние электроны** — это строго электроны самого последнего слоя (max n). **Валентные электроны** — это электроны, участвующие в образовании химических связей: для s- и p-элементов они **совпадают с внешними** (ns + np), а для d-элементов (Sc–Cu) включают ещё и предвнешний d-подуровень (ns + (n−1)d), кроме стабильного 3d¹⁰ у цинка."}, "05.5": {"t": "Модуль 05 · Внешние vs валентные электроны по семействам", "x": "• **Внешние электроны (max n)** — s- и p-элементы (подгруппа А): ns + np (равны номеру группы А; у He — 2); d-элементы Sc–Cu (подгруппа Б): Только ns (4s² → 2; у Cr, Cu 4s¹ → 1)\n• **Валентные электроны** — s- и p-элементы (подгруппа А): ns + np (совпадают с внешними!); d-элементы Sc–Cu (подгруппа Б): ns + (n−1)d (Sc=3, Ti=4, V=5, Cr=6, Mn=7, Fe=8...)\n• **Где лежат валентные e⁻** — s- и p-элементы (подгруппа А): Только на внешнем уровне (n); d-элементы Sc–Cu (подгруппа Б): На внешнем ns **и** предвнешнем (n−1)d"}, "05.7": {"t": "Модуль 05 · 2. Две тонкости на 100 баллов: цинк (Zn) и гелий (He)", "x": "• **Тонкость цинка (₃₀Zn, [Ar]3d¹⁰4s²):** формально цинк — последний d-элемент 4-го периода. Но его 3d¹⁰-подуровень полностью завершён и прочно «утоплен» вглубь оболочки, поэтому в химических связях 3d-электроны цинка **не участвуют** (степень окисления цинка в соединениях всегда +2, никогда не выше). В ЕГЭ и учебнике Ерёмина у цинка считают **2 внешних и 2 валентных электрона (4s²)**. *(У меди ₂₉Cu 3d-электроны частично участвуют в связях — отсюда Cu^{+2}, поэтому формально в школьной модели к валентным относят все 11 электронов 3d¹⁰4s¹, а у Co и Ni сумма 3d + 4s равна 9 и 10; однако в однозначных заданиях № 1 на подсчёт валентных у d-элементов ФИПИ обычно даёт Sc–Fe, особенно Cr, Mn, Fe, V, Ti.)*…"}, "05.11": {"t": "Модуль 05 · 3. Одинаковая конфигурация внешнего уровня и «электроны до завершения»", "x": "• **ns¹** (1 внешний электрон): водород H (1s¹), все щелочные металлы (Li, Na, K, Rb, Cs) **+ элементы с провалом Cr, Cu, Mo, Ag**!\n• **ns²** (2 внешних электрона): **гелий He (1s²)**, все элементы IIA группы (Be, Mg, Ca, Sr, Ba) **+ все d-элементы без провала (Sc, Ti, V, Mn, Fe, Co, Ni, Zn)**!\n• **ns²np^k**: элементы одной главной подгруппы IIIA–VIIIA (кроме гелия!). Например, у O (2s²2p⁴) и S (3s²3p⁴) одинаковая конфигурация внешнего уровня ns²np⁴."}, "05.13": {"t": "Модуль 05 · 3. Одинаковая конфигурация внешнего уровня и «электроны до завершения»", "x": "Ещё одна популярная формулировка — **«до завершения внешнего энергетического уровня недостаёт k электронов»**. Для всех элементов начиная со 2-го периода под «завершением внешнего уровня» в ЕГЭ понимают устойчивый **октет** благородного газа (ns²np⁶, 8 электронов — не путай с «полностью заполненным уровнем» по формуле 2n², разницу разберём в модуле 08!), поэтому для p-элементов число недостающих электронов равно 8 − (число внешних e⁻): галогенам (F, Cl, Br, I) не хватает 1, халькогенам (O, S, Se) — 2, пниктогенам (N, P, As) — 3, углероду и кремнию — 4. А вот для **водорода (H, 1s¹)** 1-й уровень вмещает максимум **2** электрона (дублет 1s²), поэтому до завершения ему не хватает всего **1 электрона**, ровно как фтору и хлору!"}, "05.15": {"t": "Модуль 05 · 4. Разбор вслух: две классические задачи на внешние и валентные", "x": "**Задача 1:** Из ряда 1) Li   2) B   3) Cr   4) Fe   5) N выбери два элемента с одинаковой конфигурацией внешнего уровня.\n**Шаг 2.** **Выписываем внешние уровни:** Li → 2s¹ (ns¹, **+**); B → 2s²2p¹; Cr ([Ar]3d⁵4s¹) → 4s¹ (ns¹, **+**); Fe ([Ar]3d⁶4s²) → 4s² (ns²); N → 2s²2p³. Единственная пара с одинаковой внешней конфигурацией (ns¹) — Li и Cr. Ответ: **13**.\n**Задача 2:** Из ряда 1) P  2) V  3) Cr  4) Mg  5) Zn выбери два элемента, у которых **число валентных электронов равно 5**.\n**Шаг 4.** **Считаем валентные электроны:** P (3s²3p³) → **5**; V ([Ar]3d³4s²) → 3 + 2 = **5**; Cr ([Ar]3d⁵4s¹) → 5 + 1 = 6; Mg (3s²) → 2; Zn ([Ar]3d¹⁰4s²) → 2 (3d¹⁰ не валентен). Ответ: **12** (P и V)."}, "05.16": {"t": "Модуль 05 · Ловушка ЕГЭ: не приравнивай внешние и валентные у d-металлов", "x": "Осторожно с вопросом **«число внешних электронов меньше числа валентных»** (или «валентные электроны находятся на s- и d-подуровнях»). Это прямой намёк на **переходные d-элементы (Sc–Cu)**, потому что у s- и p-элементов внешние всегда равны валентным, а у Zn 3d¹⁰ в связях не участвует!"}, "06": {"t": "Модуль 06. Основное и возбуждённое состояния атома", "x": "При переходе в **возбуждённое состояние** электронная пара внешнего уровня распадается, и один электрон переходит на **свободную орбиталь того же энергетического уровня n**. Для этого нужны сразу два условия: **неподелённая пара** и **пустая ячейка на том же n**. У N, O и F пустых ячеек на 2-м уровне нет (нет 2d-подуровня!), поэтому они **не возбуждаются**."}, "06.1": {"t": "Модуль 06 · Главная мысль.", "x": "При переходе в **возбуждённое состояние** электронная пара внешнего уровня распадается, и один электрон переходит на **свободную орбиталь того же энергетического уровня n**. Для этого нужны сразу два условия: **неподелённая пара** и **пустая ячейка на том же n**. У N, O и F пустых ячеек на 2-м уровне нет (нет 2d-подуровня!), поэтому они **не возбуждаются**."}, "06.8": {"t": "Модуль 06 · 2. Элементы 2-го периода: почему B и C возбуждаются, а N, O, F — нет", "x": "• **₄Be (2s²2p⁰):** есть пара 2s² и три пустые клетки 2p → переход 2s² → 2s¹2p¹ (было 0 неспаренных, стало **2**).\n• **₅B (2s²2p¹):** есть пара 2s² и две пустые клетки 2p → переход 2s²2p¹ → 2s¹2p² (было 1, стало **3**).\n• **₆C (2s²2p²):** есть пара 2s² и одна пустая клетка 2p → переход 2s²2p² → 2s¹2p³ (было 2, стало **4** — отсюда четырёхвалентность углерода в органике и CO2!).\n• **₇N (2s²2p³), ₈O (2s²2p⁴), ₉F (2s²2p⁵):** все три клетки 2p уже заняты (у азота ↑ ↑ ↑, у кислорода ↑↓ ↑ ↑, у фтора ↑↓ ↑↓ ↑), а подуровня **2d не существует**! Распаривать пару 2s² (или 2p-пары) просто **некуда**."}, "06.12": {"t": "Модуль 06 · 3. Элементы 3-го периода: появление 3d-подуровня и ступени возбуждения", "x": "• **₁₄Si** — 3s²3p² (2); 3s¹3p³ (4); —; —\n• **₁₅P** — 3s²3p³ (3); 3s¹3p³3d¹ (5); —; —\n• **₁₆S** — 3s²3p⁴ (2); 3s²3p³3d¹ (4); 3s¹3p³3d² (6); —\n• **₁₇Cl** — 3s²3p⁵ (1); 3s²3p⁴3d¹ (3); 3s²3p³3d² (5); 3s¹3p³3d³ (7)"}, "06.16": {"t": "Модуль 06 · 4. Разбор вслух: кто может и кто не может перейти в возбуждённое состояние", "x": "**Задача:** Дан ряд элементов: 1) N   2) P   3) O   4) S   5) F. Определи, какие элементы ряда **не могут** перейти в возбуждённое состояние в пределах внешнего уровня, и выбери два элемента, которые **могут** иметь в возбуждённом состоянии 4 или 5 неспаренных электронов.\n**Шаг 2.** **Проверяем 2-й период (N, O, F):** у всех троих 2p-ячейки полностью заняты (нет ни одной пустой клетки), а 2d-подуровня не существует. Значит, N, O и F в возбуждённое состояние **не переходят**.\n**Шаг 3.** **Проверяем 3-й период (P, S):** у ₁₅P (3s²3p³) есть пара 3s² и пустой 3d → переходит в 3s¹3p³3d¹ (**5 неспаренных**). У ₁₆S (3s²3p⁴) есть две пары (3p и 3s) и пустой 3d → первое возбуждённое 3s²3p³3d¹ (**4 неспаренных**), второе 3s¹3p³3d² (**6 неспаренных**).…"}, "06.17": {"t": "Модуль 06 · Ловушка ЕГЭ: S возбуждается до 6 неспаренных, а O — нет!", "x": "На ЕГЭ любят ловушку со словами **«в возбуждённом состоянии»**: например, «имеют в возбуждённом состоянии конфигурацию внешнего уровня ns¹np²» → это элементы IIIA группы (B, Al, Ga), а «ns¹np³» → элементы IVA группы (C, Si, Ge). Никогда не путай O с S и N с P — они в одних группах, но у 2-го периода (N, O, F) возбуждённого состояния нет!"}, "07": {"t": "Модуль 07. Электронные конфигурации ионов и благородных газов", "x": "При образовании **катиона (X^{k+})** атом отдаёт k электронов с **самого внешнего уровня** (у d-металлов 4-го периода **сначала уходят 4s-электроны**, и только потом 3d). При образовании **аниона (X^{m−})** атом принимает m электронов на ближайший свободный подуровень. Конфигурацию **благородного газа** имеют только оболочки 1s² ([He]) и ns²np⁶ ([Ne], [Ar], [Kr]), но **не** 18-электронная [Ar]3d¹⁰!"}, "07.1": {"t": "Модуль 07 · Главная мысль.", "x": "При образовании **катиона (X^{k+})** атом отдаёт k электронов с **самого внешнего уровня** (у d-металлов 4-го периода **сначала уходят 4s-электроны**, и только потом 3d). При образовании **аниона (X^{m−})** атом принимает m электронов на ближайший свободный подуровень. Конфигурацию **благородного газа** имеют только оболочки 1s² ([He]) и ns²np⁶ ([Ne], [Ar], [Kr]), но **не** 18-электронная [Ar]3d¹⁰!"}, "07.3": {"t": "Модуль 07 · 1. Катионы, анионы и строгий стандарт записи зарядов", "x": "Нейтральный атом может отдать или принять электроны — тогда число протонов в ядре (Z) остаётся прежним, а баланс зарядов нарушается и образуется **ион**:"}, "07.5": {"t": "Модуль 07 · Стандарт ЕГЭ: заряд иона (2+) vs степень окисления (+2)", "x": "Сразу привыкай к строгому стандарту части 2 ФИПИ (задания 29–30): **заряд иона** всегда пишется **цифрой перед знаком** (Fe^{2+}, Fe^{3+}, O^{2−}, S^{2−}, Al^{3+}), а **степень окисления** — **знаком перед цифрой** (Fe^{+2}, O^{−2}, S^{−2}). За перепутанный порядок знака и цифры в ионных уравнениях на ЕГЭ снимают балл!"}, "07.7": {"t": "Модуль 07 · 2. Главное правило ионизации d-металлов: 4s уходит раньше 3d!", "x": "В модуле 03 мы видели, что при **заполнении** нейтрального атома 4s идёт раньше 3d. Но как только 3d-подуровень начал заполняться, электроны на 3d оказываются **ближе к ядру** (на 3-м слое), а 4s-электроны остаются на **самом дальнем, внешнем 4-м слое**. Оторвать электрон легче с внешнего слоя, поэтому действует железное правило:"}, "07.8": {"t": "Модуль 07 · Почему 4s заполняется раньше 3d, но уходит тоже раньше?", "x": "При ионизации любого d-металла 4-го периода электроны **всегда сначала уходят с внешнего 4s-подуровня**, и только после полного опустошения 4s — с предвнешнего 3d-подуровня! Именно поэтому в модуле 03 мы договорились сразу писать ...3d^k 4s^m — внешний 4s стоит справа на краю и уходит первым."}, "07.12": {"t": "Модуль 07 · 3. Изоэлектронные частицы и ловушка «конфигурация инертного газа»", "x": "• ****₂He** (2 e⁻)** — Конфигурация: 1s²; Кто имеет такую же конфигурацию (изоэлектронный ряд): H⁻, Li⁺, Be^{2+}\n• ****₁₀Ne** (10 e⁻)** — Конфигурация: 1s²2s²2p⁶; Кто имеет такую же конфигурацию (изоэлектронный ряд): N^{3−}, O^{2−}, F⁻, Na⁺, Mg^{2+}, Al^{3+}\n• ****₁₈Ar** (18 e⁻)** — Конфигурация: 1s²2s²2p⁶3s²3p⁶; Кто имеет такую же конфигурацию (изоэлектронный ряд): P^{3−}, S^{2−}, Cl⁻, K⁺, Ca^{2+}, **Sc^{3+}**\n• ****₃₆Kr** (36 e⁻)** — Конфигурация: [Ar]3d¹⁰4s²4p⁶; Кто имеет такую же конфигурацию (изоэлектронный ряд): Se^{2−}, Br⁻, Rb⁺, Sr^{2+}"}, "07.13": {"t": "Модуль 07 · Ловушка ЕГЭ: [Ar]3d¹⁰ — это НЕ конфигурация благородного газа!", "x": "Тончайшая ловушка на 95–100 баллов! Посмотри на ионы **Cu⁺**, **Zn^{2+}**, **Ga^{3+}** и **Ge^{4+}**. У всех четверых остаётся 28 электронов, и их конфигурация — **[Ar]3d¹⁰** (1s²2s²2p⁶3s²3p⁶3d¹⁰). У них **НЕ** конфигурация аргона (18 e⁻) и **НЕ** конфигурация криптона (36 e⁻)! Это 18-электронная (псевдоинертная) внешняя оболочка 3-го слоя (3s²3p⁶3d¹⁰). Зато у **Sc^{3+}** (отдал 4s² и 3d¹) остаётся ровно [Ar] — конфигурация благородного газа! И не попадись на катион водорода **H⁺**: у него вообще **0 электронов**, поэтому в отличие от гидрид-иона H⁻ (1s² = [He]) катион H⁺ **не имеет** конфигурации благородного газа."}, "07.15": {"t": "Модуль 07 · 4. Разбор вслух: составляем конфигурации сложных ионов", "x": "**Задача:** Составь электронные конфигурации ионов S^{2−}, Ca^{2+}, Sc^{3+}, Cr^{3+}, Fe^{2+}, Fe^{3+}, Cu⁺, Zn^{2+}, Ga^{3+} и укажи, какие из них имеют конфигурацию благородного газа.\n**Шаг 2.** **S^{2−} (16 + 2 = 18 e⁻):** атом серы [Ne]3s²3p⁴ принимает 2 электрона в 3p → [Ne]3s²3p⁶ = **[Ar]** (конфигурация аргона — ДА).\n**Шаг 3.** **Ca^{2+} (20 − 2 = 18 e⁻):** атом кальция [Ar]4s² отдаёт 4s² → **[Ar]** (ДА).\n**Шаг 4.** **Sc^{3+} (21 − 3 = 18 e⁻):** атом скандия [Ar]3d¹4s² отдаёт сначала 4s², затем 3d¹ → **[Ar]** (ДА).\n**Шаг 5.** **Cr^{3+} (24 − 3 = 21 e⁻):** атом хрома [Ar]3d⁵4s¹ отдаёт 1 электрон с 4s¹ и 2 электрона с 3d⁵ → **[Ar]3d³** (3 неспаренных; НЕТ).\n**Шаг 6.** **Fe^{2+} и Fe^{3+}:** атом железа [Ar]3d⁶4s² → у Fe^{2+} уходят 4s² → **[Ar]3d⁶** (4 неспаренных); у Fe^{3+} уходит ещё 1 электрон с 3d → **[Ar]3d⁵** (5 неспаренных; НЕТ).…"}, "08": {"t": "Модуль 08. Все формулировки задания № 1 КИМ и алгоритм безошибочного решения", "x": "В задании № 1 всегда даны **5 элементов** и нужно выбрать ровно **2** номера (порядок цифр не важен, 1 первичный балл). Безошибочная стратегия занимает 60–90 секунд: **сначала выпиши конфигурации всех пяти элементов**, затем **подчеркни слова-переключатели в условии** и проверь каждый элемент по всем критериям сразу."}, "08.1": {"t": "Модуль 08 · Главная мысль.", "x": "В задании № 1 всегда даны **5 элементов** и нужно выбрать ровно **2** номера (порядок цифр не важен, 1 первичный балл). Безошибочная стратегия занимает 60–90 секунд: **сначала выпиши конфигурации всех пяти элементов**, затем **подчеркни слова-переключатели в условии** и проверь каждый элемент по всем критериям сразу."}, "08.8": {"t": "Модуль 08 · 3. Единый 5-шаговый алгоритм решения на экзамене", "x": "1. **Найди все 5 элементов в таблице ФИПИ:** подпиши прямо в КИМ их Z, период и подгруппу (А или Б).\n2. **Выпиши конфигурации всех пяти элементов:** для 1–3 периодов — полную, для 4-го — [Ar]3d^k 4s^m, сразу помечая восклицательным знаком Cr (3d⁵4s¹) и Cu (3d¹⁰4s¹).\n3. **Подчеркни слова-переключатели в условии:** *основное/возбуждённое*, *внешние/валентные/всего*, *полностью заполненные/содержащие электроны*, *атом/ион*.\n4. **Поставь «+» или «−» каждому из пяти элементов** (проверив **все** части условия, если оно комбинированное).\n5. **Сверь число ответов:** в задании № 1 их всегда ровно **два**. Если получилось три — ищи пропущенную тонкость (He, Cr, Cu, Zn, N/O/F, [Ar]3d¹⁰). Запиши две цифры без пробелов (порядок не важен)."}, "08.10": {"t": "Модуль 08 · 4. Пять полных экзаменационных разборов сложных прототипов", "x": "**Шаг 1.** **Прототип 1 (провал + внешний уровень ns¹):** Ряд: 1) K   2) Be   3) Cu   4) N   5) P. *Условие:* «На внешнем энергетическом уровне в основном состоянии находится ровно 1 электрон». **Разбор:** K ([Ar]4s¹ → 1, **+**), Be (2s² → 2), Cu ([Ar]3d¹⁰4s¹ → провал! **1**, **+**), N (2s²2p³ → 5), P (3s²3p³ → 5). **Ответ: 13.**\n**Шаг 2.** **Прототип 2 (валентные vs внешние электроны):** Ряд: 1) Cr   2) S   3) Mn   4) Mg   5) Zn. *Условие:* «Число валентных электронов равно 6». **Разбор:** Cr ([Ar]3d⁵4s¹ → валентные 3d⁵ + 4s¹ = **6**, **+**), S ([Ne]3s²3p⁴ → **6**, **+**), Mn (3d⁵4s² → 7), Mg (3s² → 2), Zn ([Ar]3d¹⁰4s² → 3d¹⁰ не валентен → 2). **Ответ: 12.**…"}, "08.11": {"t": "Модуль 08 · Ловушка на 100 баллов: уровень vs подуровень vs орбиталь", "x": "Отдельно различай четыре термина и два похожих определения: **«уровень, содержащий электроны»** (= номер периода), **«завершённый внешний уровень»** (октет ns²np⁶ или дублет 1s², например у ₁₈Ar внешний уровень завершён), **«полностью заполненный уровень»** (по формуле 2n²: у ₁₁Na, ₁₈Ar и ₁₉K–₂₈Ni полностью заполнены только 2 уровня — 1-й и 2-й, потому что 3-й вмещает 18 e⁻ и на нём пуст или недозаполнен 3d! Полностью заполненным 3-й уровень становится только начиная с **₂₉Cu и ₃₀Zn** — 3s²3p⁶3d¹⁰ = 18 e⁻ — и далее у Ga–Kr), **«занятый подуровень»** (число слагаемых в полной записи: у C 1s²2s²2p² их 3) и **«занятая орбиталь»** (клетка с хотя бы одним электроном: у C их 1 + 1 + 2 = 4, а полностью заполненных орбиталей — 2)."}}, "_kt": "Задание 1 · Строение атома и электронные конфигурации", "_mods": {"01": "Атом, ядро и чёрно-белая таблица ФИПИ", "02": "Энергетические уровни, орбитали, принцип Паули и правило Хунда", "03": "Правило Клечковского, семейства s, p, d и подсчёт электронов", "04": "d-элементы 4-го периода и провал электрона (Cr, Cu)", "05": "Внешние, предвнешние и валентные электроны", "06": "Основное и возбуждённое состояния атома", "07": "Электронные конфигурации ионов и благородных газов", "08": "Все формулировки задания № 1 КИМ и алгоритм безошибочного решения"}, "_skm": {"atom_pshe": ["01"], "orbitals_hund": ["02"], "klechkovsky_spd": ["03"], "d_promotion": ["04"], "outer_valence": ["05"], "excited_state": ["06"], "ions_noble": ["07"], "kim1_strategy": ["08"]}, "_fig": []};
